-- 투데이오늘: 로컬(서울·경기·인천·강원·충청·영남·호남·제주) 시작 기사 39건 — 승인대기, 정부·지자체·공공기관 보도자료를 바탕으로 새로 쓴 기사
-- Supabase SQL 에디터에서 실행 (newstoday-sections.sql 다음). 여러 번 실행해도 된다 (같은 제목 기사는 건너뛴다)
--   · 사진: 저장소의 /sites/newstoday/photos/ 에 있는 이미지를 쓴다 (배포가 끝난 뒤에 사진이 보인다)
--   · 작성: 투데이오늘 관리자 계정(없으면 편집장 → 총관리자), 기자명 '편집국'
--   · 기사마다 '확인할 점'·원문 주소·사진 이용 조건을 AI 메모(편집 메모)에 남겼다

with ctx as (
  select o.id as outlet_id, o.name as outlet_name,
         coalesce(
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'admin' order by p.created_at limit 1),
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'editor' order by p.created_at limit 1),
           (select p.id from profiles p where (to_jsonb(p) ->> 'is_super') = 'true' order by p.created_at limit 1),
           (select p.id from profiles p where p.role = 'admin' order by p.created_at limit 1)
         ) as author_id
  from outlets o
  where o.name = '투데이오늘'
)
insert into articles (outlet_id, category_id, author_id, title, body, excerpt, thumbnail_url, status, published_at, tags, press_release_id)
select ctx.outlet_id, c.id, ctx.author_id, v.title,
       replace(v.body, '@@BYLINE@@', '[' || ctx.outlet_name || '=편집국]'),
       v.excerpt, v.thumb, v.status, v.published_at, v.tags,
       null
from ctx
cross join (values
  ('seoul', '청계천 자율주행버스 ''청계 A01'', 22일부터 야간 정기운행', '<p>@@BYLINE@@&nbsp;서울시는 오는 22일 오후 7시부터 청계천 자율주행버스 ''청계 A01''의 야간운행을 시작한다. 서울시는 20일 보도자료에서 운전대와 운전석이 없는 자율주행버스를 야간 시간대에 정기 운행하는 것은 국내 최초라고 밝혔다.</p><p>청계 A01 노선은 청계광장에서 청계3가(세운상가)를 거쳐 청계5가(광장시장)까지 왕복 4.8km 구간이다. 차량 2대가 순환 운행하며 양방향으로 모두 11개 정류소에 정차한다.</p><img src="/sites/newstoday/photos/ntd-seoul-1.webp" alt="청계천이 시작되는 지점의 폭포 야경(자료사진, 자율주행버스 사진 아님). 사진=fillter, 위키미디어 공용 (CC0)"><p><em>▲ 청계천이 시작되는 지점의 폭포 야경(자료사진, 자율주행버스 사진 아님). 사진=fillter, 위키미디어 공용 (CC0)</em></p><p>운행은 오후 7시에 시작해 청계광장 기준 30분 간격으로 하루 9회 이뤄지고, 청계광장 막차는 오후 11시에 출발한다. 네이버지도와 카카오맵 등에서 ''청계 A01''을 검색하면 정류소 위치와 실시간 운행정보를 확인할 수 있다.</p><p>서울시는 지난 8월 18일부터 31일까지 야간 시간대 시범운행을 했고, 외부 전문가와 함께 안전성을 미리 검증했다고 설명했다. 노선 주변에는 광화문광장과 보신각, 종각·관철동 음식점 거리, 을지로 상권, 광장시장 등이 있다.</p><p>이번 야간운행 개편에 따라 기존 주간운행은 종료된다. 서울시는 자율주행버스를 정규 대중교통수단으로 정착시키기 위해 단계적인 유료화도 추진할 예정이다. 다만 야간운행 초기에는 요금을 받지 않으며, 탑승할 때 교통카드는 태그해야 한다.</p><p>서울시는 2025년 8월부터 2026년 9월까지 약 1년간 무료 실증을 거쳤다고 밝혔다. 여장권 서울시 교통실장은 "청계천 자율주행버스의 야간운행은 미래교통 기술을 시민이 일상에서 경험하는 것을 넘어, 청계천의 야경과 종각·을지로 등 주변 지역을 편리하게 연결해 서울의 밤을 더욱 풍성하게 즐길 수 있는 새로운 이동 경험을 선사할 것"이라고 말했다.</p>', '서울시는 10월 22일 오후 7시부터 청계천 자율주행버스 ''청계 A01''의 야간운행을 시작한다. 청계광장에서 광장시장까지 왕복 4.8km 구간을 하루 9회 운행하며, 초기에는 무료로 운영한다.', '/sites/newstoday/photos/ntd-seoul-1.webp', '2026-10-20T10:20:00+09:00'::timestamptz, array['서울','청계천','자율주행버스','야간운행','대중교통']::text[], 'in_review'),
  ('seoul', '광화문광장 감사의 정원 방문객 50만 명 넘어…스웨덴 행사 열려', '<p>@@BYLINE@@&nbsp;서울시는 21일 보도자료에서 광화문광장 ''감사의 정원''의 누적 방문객이 50만 명을 넘었다고 밝혔다. 10월 19일 기준 집계는 500,157명이다.</p><p>이 집계는 방문자 AI 자동 집계 시스템으로 2026년 5월 13일부터 10월 19일까지 합산한 것이다. 지하 실내 공간인 ''프리덤 홀'' 방문객과 지상부 조형물 ''감사의 빛 23'' 방문객이 함께 포함됐고, 서울시는 개장 160일 만의 성과라고 설명했다.</p><img src="/sites/newstoday/photos/ntd-seoul-2.webp" alt="광화문광장 전경(자료사진, 감사의 정원 모습 아님). 사진=Tristan Surtel, 위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 광화문광장 전경(자료사진, 감사의 정원 모습 아님). 사진=Tristan Surtel, 위키미디어 공용 (CC BY-SA 4.0)</em></p><p>감사의 정원은 6·25전쟁 참전국과 참전용사에게 감사를 전하고 자유와 평화의 가치를 되새기기 위해 마련된 공간이다. 지하 프리덤 홀에서는 미디어 콘텐츠로 6·25전쟁의 역사와 대한민국의 성장 이야기를 볼 수 있다.</p><p>주한 스웨덴 대사관은 지난 8월 스웨덴산 시에나이트를 기증해 ''감사의 빛 23''에 양국의 우정을 더했다. 서울시는 감사의 정원 준공 이후 참전국이 석재를 기증·설치한 첫 사례라고 밝혔다. 스웨덴은 6·25전쟁 당시 야전병원을 파견해 의료 지원에 나선 나라다.</p><p>서울시는 이를 기념해 10월 24일과 25일 이틀간 광화문광장에서 ''글로벌문화데이-스웨덴''을 연다. ''2026 광화문 빛모락 축제''와 연계한 행사로, 강연과 공연, 영화 상영, 체험 부스 등으로 구성된다.</p><p>24일 오후 7시 40분 특설무대에서는 석재 기증 기념행사가 열리고, 스웨덴 국기를 상징하는 노란색과 파란색 조명을 활용한 ''감사의 빛 23'' 특별 점등이 이어진다. 오후 5시에는 식전행사로 역사 전문가의 강연이 마련된다. 24일과 25일 정오에는 스웨덴 가족영화 ''말괄량이 삐삐''가 상영된다.</p><p>강석 서울시 균형발전본부장은 "앞으로도 참전국과의 교류를 꾸준히 넓혀, 감사의 정원을 세대와 국경을 넘어 전 세계인이 연대하는 공간으로 만들어 가겠다"고 밝혔다.</p>', '서울시는 광화문광장 감사의 정원 누적 방문객이 10월 19일 기준 50만 명을 넘었다고 밝혔다. 24일과 25일에는 스웨덴의 석재 기증을 기념하는 ''글로벌문화데이-스웨덴''이 열린다.', '/sites/newstoday/photos/ntd-seoul-2.webp', '2026-10-21T09:40:00+09:00'::timestamptz, array['서울','광화문광장','감사의 정원','스웨덴','6·25 참전국']::text[], 'in_review'),
  ('seoul', '서울, 타임아웃 세계 대중교통 도시 5위…CNN도 서울 지하철 소개', '<p>@@BYLINE@@&nbsp;서울시는 21일 보도자료에서 영국 도시문화·여행 전문매체 타임아웃(Time Out)이 서울을 ''세계 대중교통 우수도시'' 5위로 선정했다고 밝혔다. 타임아웃이 13일(현지시간) 발표한 ''2026 세계 최고의 대중교통 도시''에서 서울은 지난해 8위보다 3계단 올랐다.</p><p>서울시에 따르면 시민 긍정 평가는 84%에서 91.1%로 7.1%p 높아졌다. 전 세계 2만 4천여 명을 대상으로 한 조사에서 1~4위는 타이베이(95.0%), 싱가포르(93.5%), 홍콩(92.8%), 에든버러(92.4%)였고, 서울은 6위 취리히, 7위 빈보다 높은 평가를 받았다.</p><img src="/sites/newstoday/photos/ntd-seoul-3.webp" alt="서울 지하철 2호선 전동차(자료사진). 사진=Mtattrain, 위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 서울 지하철 2호선 전동차(자료사진). 사진=Mtattrain, 위키미디어 공용 (CC BY-SA 4.0)</em></p><p>타임아웃은 서울의 광범위한 지하철망과 청결한 객차, 지하에서도 원활한 휴대전화 통신환경, 합리적인 요금을 강점으로 소개했다. 미국 CNN도 17일(현지시간) ''세계 최고의 지하철 시스템 18곳'' 기사에서 서울 지하철의 청결성과 안전성, 효율성을 평가했다고 서울시는 전했다.</p><p>서울시는 호평의 배경으로 승강장 안전문(스크린도어)과 교통약자 이동편의시설, 첨단 교통기술 등에 오랜 기간 투자해 온 점을 꼽았다. 스크린도어는 2009년 지하철 1~8호선 262개 전 역사에 설치를 마쳤고, 2025년 기준 9호선과 우이신설선 등을 포함해 345개 역사에 설치돼 있다.</p><p>서울시는 설치 전 연평균 37.1명(2001~2009년)이던 지하철 사고 사망자가 설치 후 0.4명(2010~2024년)으로 약 99% 줄었다고 설명했다. 2025년에는 해당 사고 사망자가 없었다.</p><p>교통약자 이동권도 개선됐다고 서울시는 밝혔다. 지난해 12월 서울시 관리 지하철 338개 전 역사에서 휠체어 이용자와 어르신 등이 도움 없이 엘리베이터로 지상에서 승강장까지 이동할 수 있는 ''1역사 1동선''을 확보했다는 것이다. 2007년 종합계획 수립 이후 18년간 약 1,751억 원이 들어갔다.</p><p>이 밖에 2023년 우이신설선에서 세계 최초로 상용화한 ''태그리스'' 요금 결제 서비스와 올해 3월부터 1~8호선 273개 역사 발매기 440대에서 가능해진 해외 신용·체크카드 승차권 구매도 소개했다. 서울시는 앞으로도 지하철 안전시설을 보강하고 교통약자 편의와 첨단 서비스를 확대할 계획이라고 밝혔다.</p>', '서울시는 영국 매체 타임아웃의 ''2026 세계 최고의 대중교통 도시''에서 서울이 5위를 차지했고, 미국 CNN도 서울 지하철의 청결성과 안전성, 효율성을 높이 평가하는 기사를 냈다고 21일 밝혔다.', '/sites/newstoday/photos/ntd-seoul-3.webp', '2026-10-21T10:50:00+09:00'::timestamptz, array['서울','지하철','타임아웃','대중교통','스크린도어']::text[], 'in_review'),
  ('seoul', '서울시, 자치구 생활권 ''서울별빛명소'' 조성…10월 말 10곳 선정', '<p>@@BYLINE@@&nbsp;서울시는 20일 보도자료에서 자치구 공모로 야간 여가 공간을 발굴하는 ''서울별빛명소 조성사업''을 추진한다고 밝혔다. 야간명소가 한강과 도심 등 일부 지역에 집중돼 이용하기 어렵다는 시민 의견을 반영해, 야간 여가의 무대를 생활권으로 넓히는 데 중점을 둔다.</p><p>서울시는 올해 10개소를 시작으로 2028년까지 모두 25개소의 야간명소를 단계적으로 만들 계획이다. 선정된 자치구에는 조성비를 최대 10억 원까지 지원하고, 자치구는 사업비를 자율적으로 분담한다.</p><img src="/sites/newstoday/photos/ntd-seoul-4.webp" alt="한강 반포대교 달빛무지개분수의 야경(자료사진, 별빛명소 후보지 사진 아님). 사진=Wvdp, 위키미디어 공용 (CC0)"><p><em>▲ 한강 반포대교 달빛무지개분수의 야경(자료사진, 별빛명소 후보지 사진 아님). 사진=Wvdp, 위키미디어 공용 (CC0)</em></p><p>공모는 지난 8월 26일부터 9월 16일까지 25개 전 자치구를 대상으로 진행됐다. 21개 자치구가 27개 후보지를 신청했다. 유형별로는 자연·웰니스형 10개, 문화·예술형 7개, 역사·유적형 3개, 전망·랜드마크형 3개, 기타(복합)형 4개다.</p><p>서울시는 10월 2일 1차 평가에서 16개 자치구 18개 후보지를 2차 평가 대상으로 선정했다. 21일과 22일 현장평가를 거쳐 10월 말 최종 선정 결과를 공개할 예정이다. 심사는 내·외부 전문가 8명으로 구성된 심사위원회가 맡는다.</p><p>서울시는 지난 7월 시민 1,000명을 대상으로 한 설문에서 응답자의 82.6%가 거주지에 야간명소가 조성되면 이용할 의향이 있다고 답했다고 밝혔다. 선호하는 야간 콘텐츠는 공원·수변 산책로(44.2%), 야장(37.8%), 고궁·박물관 개장(33.3%) 순이었다.</p><p>최종 선정된 자치구는 2027년 12월까지 후보지 특성에 맞춰 야간명소를 조성한다. 서울시는 완공 이후 방문객과 체류시간, 인근 상권 매출 변화 등 사업 효과를 분석해 후속 사업에 반영할 계획이다.</p><p>김현우 서울시 경제실장은 "서울의 밤을 한강과 도심을 넘어 25개 자치구 골목 구석구석으로 펼치고, 늘어난 발길이 상권의 활력으로 돌아오는 야간경제 선순환을 정착시키겠다"고 말했다.</p>', '서울시는 한강과 도심에 몰린 야간명소를 자치구 생활권으로 넓히는 ''서울별빛명소 조성사업''을 추진한다. 올해 10곳을 시작으로 2028년까지 25곳을 조성한다는 계획이며, 10월 말 최종 선정 결과를 공개한다.', '/sites/newstoday/photos/ntd-seoul-4.webp', '2026-10-20T11:36:00+09:00'::timestamptz, array['서울','서울별빛명소','야간경제','자치구','야간명소']::text[], 'in_review'),
  ('gyeonggi', '안산 경기지방정원 ''새로숲''에 11월부터 나무 심는다', '<p>@@BYLINE@@&nbsp;경기도가 안산시 상록구 본오동 일원에 조성 중인 경기지방정원 ''새로숲''에 오는 11월부터 나무를 심는다. 경기도는 21일 보도자료에서 이같이 밝혔다.</p><p>새로숲은 과거 생활폐기물을 매립하던 안산시화매립지를 꽃과 나무가 어우러진 생태·문화 공간으로 바꾸는 사업이다. 경기도는 기존 숲을 활용하는 일반적인 정원과 달리 오랫동안 쓰레기매립지로 쓰인 땅에 나무를 심어 새로운 숲을 만든다는 점이 다르다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-gyeonggi-1.webp" alt="경기도가 안산시에 조성 중인 경기지방정원 &#x27;새로숲&#x27; 조성 현장을 공중에서 촬영한 모습. ⓒ경기도 (공공누리 제1유형)"><p><em>▲ 경기도가 안산시에 조성 중인 경기지방정원 ''새로숲'' 조성 현장을 공중에서 촬영한 모습. ⓒ경기도 (공공누리 제1유형)</em></p><p>이번에는 식재가 가능한 일부 구역만을 대상으로 모두 300여 본을 심는다. 경기도는 양버즘나무, 아까시나무, 루브룸단풍나무, 느티나무, 계수나무 5개 수종을 대표 나무로 정하고 각각 극복·회복·성장·기억·감성이라는 의미를 부여했다.</p><p>과거 쓰레기선별장 시절부터 자리를 지켜 온 느티나무는 ''기억의 나무''로, 척박한 토양을 비옥하게 만드는 아까시나무는 ''회복의 나무''로 활용한다. 가을철 낙엽에서 달콤한 향이 나는 계수나무는 ''감성의 나무''로 정했다. 양버즘나무와 루브룸단풍나무에는 각각 극복과 성장의 의미를 담는다.</p><p>경기도는 이번 가을철 식재를 시작으로 식재 구역을 넓혀 나갈 방침이다. 이를 통해 매립장이었던 공간을 도민이 자연 속에서 휴식과 여가를 즐기는 녹색 공간으로 바꾸고, 이산화탄소 흡수와 미세먼지 저감 등 도시환경 개선에도 기여할 것으로 기대한다고 밝혔다.</p><p>새로숲은 총사업비 989억 원을 들여 45만㎡ 규모로 조성한다. 2025년 7월 공사를 시작했으며 2028년 개원을 목표로 하고 있다. 인접한 안산갈대습지와 연계해 정원과 습지가 하나의 녹색 공간으로 이어지도록 할 계획이다.</p><p>이태선 경기도 정원산업과장은 "과거 쓰레기매립장이었던 새로숲이 자연의 생명력을 되찾고 도민 모두가 누리는 녹색자산으로 거듭날 수 있도록 조성에 최선을 다하겠다"고 말했다.</p>', '경기도는 안산시 상록구 본오동 일원에 조성 중인 경기지방정원 ''새로숲''에 11월부터 나무를 심는다고 밝혔다. 과거 쓰레기매립지였던 곳으로, 2028년 개원을 목표로 하고 있으며 총사업비는 989억 원이다.', '/sites/newstoday/photos/ntd-gyeonggi-1.webp', '2026-10-21T09:12:00+09:00'::timestamptz, array['경기도','안산','새로숲','경기지방정원','쓰레기매립지']::text[], 'in_review'),
  ('gyeonggi', '포천서 경기북부 긴급구조종합훈련…헬기 추락 복합재난 가정', '<p>@@BYLINE@@&nbsp;경기도북부소방재난본부는 지난 19일 포천시 군내면 웰플렉스 지식산업센터에서 대형 복합재난에 대비한 ''2026년 경기북부 긴급구조종합훈련''을 실시했다. 경기도는 20일 보도자료에서 이같이 밝혔다.</p><p>훈련은 경기도북부소방재난본부와 포천소방서가 공동 주관했다. 소방·경찰·군·포천시·의료기관 등 25개 기관·단체에서 416명이 참여했고 장비 71대가 동원됐다.</p><p>훈련은 민간헬기가 복합건축물에 추락해 대형화재와 다수 사상자가 발생하는 상황을 가정해 진행됐다. 화재 확대와 통신 두절, 건물 붕괴 등 돌발 상황은 불시 메시지로 부여해 현장지휘관의 위험 판단과 지휘체계, 관계기관 간 협력체계를 점검했다.</p><img src="/sites/newstoday/photos/ntd-gyeonggi-2.webp" alt="경기북부 긴급구조종합훈련에서 연기가 가득한 건물 내부로 진입하는 소방대원들. ⓒ경기도 (공공누리 제1유형)"><p><em>▲ 경기북부 긴급구조종합훈련에서 연기가 가득한 건물 내부로 진입하는 소방대원들. ⓒ경기도 (공공누리 제1유형)</em></p><p>특히 재난현장에서 활동하는 소방대원의 안전 확보에 중점을 뒀다. 현장 상황 변화에 따른 위험요인 파악과 대원 안전관리, 통신 두절 시 대응체계를 점검하고 소방대원 고립 상황을 가정한 신속대응팀(RIT) 가동훈련도 했다.</p><p>아울러 지휘·소통·임무수행·기관 간 협업을 중심으로 한 ''4C 현장대응체계''가 제대로 작동하는지 확인했다고 밝혔다.</p><p>김문용 경기도북부소방재난본부장은 "도민의 생명을 지키는 일과 함께 현장에서 임무를 수행하는 소방대원의 안전을 확보하는 것 역시 무엇보다 중요한 책무"라고 말했다. 이어 지휘와 대응체계를 지속적으로 점검해 "안타까운 순직사고가 반복되지 않도록 최선을 다하겠다"고 밝혔다.</p>', '경기도북부소방재난본부는 19일 포천시 군내면에서 민간헬기 추락에 따른 대형 복합재난을 가정한 긴급구조종합훈련을 했다. 25개 기관·단체 416명과 장비 71대가 참여해 대응체계를 점검했다.', '/sites/newstoday/photos/ntd-gyeonggi-2.webp', '2026-10-20T08:30:00+09:00'::timestamptz, array['경기북부','포천','소방','긴급구조훈련','재난대응']::text[], 'in_review'),
  ('gyeonggi', '경기도주식회사·연천 전곡농협, 연천쌀 미국 수출 선적식', '<p>@@BYLINE@@&nbsp;경기도주식회사는 20일 연천군 전곡농협에서 연천 특화 신품종 ''연진''을 활용한 ''매일첫쌀 연천쌀''의 미국 수출 기념 선적식을 열었다. 경기도는 이날 보도자료에서 이같이 밝혔다.</p><p>이번 수출은 경기도주식회사가 해외 오프라인 판로 지원사업의 하나로 전곡농협과 협력해 추진했다. ''연진''은 ''연천의 보배 귀한 맛''이라는 의미를 담은 신품종으로, 4kg 제품 1,000포대가 미국 한양마트 뉴욕·뉴저지 지점에 공급된다.</p><img src="/sites/newstoday/photos/ntd-gyeonggi-3.webp" alt="20일 연천군 전곡농협에서 열린 연천쌀 미국 수출 기념 선적식 현장. ⓒ경기도 (공공누리 제1유형)"><p><em>▲ 20일 연천군 전곡농협에서 열린 연천쌀 미국 수출 기념 선적식 현장. ⓒ경기도 (공공누리 제1유형)</em></p><p>두 기관은 미국 현지 소비자와의 접점을 넓히기 위해 미국 내 신규 유통망을 확보하고 현지 프로모션을 추진할 계획이다. 판매 추이에 따라 추가 수출도 진행한다.</p><p>경기도주식회사는 이번 쌀 수출을 시작으로 올해 해외 오프라인 판로 지원사업을 본격 시작한다. 일본과 중국, 미국 등에 경기도 쌀과 중소기업 뷰티 제품, 반려동물 용품 등을 수출한다는 계획이다.</p><p>경기도주식회사 관계자는 "이번 연천쌀 미국 수출이 지역 농산물의 해외 판로 확대와 참여 기업의 매출 증대에 도움이 되길 기대한다"고 말했다.</p>', '경기도주식회사는 20일 연천군 전곡농협에서 신품종 ''연진''을 활용한 ''매일첫쌀 연천쌀''의 미국 수출 기념 선적식을 열었다. 4kg 제품 1,000포대가 미국 한양마트 뉴욕·뉴저지 지점에 공급된다.', '/sites/newstoday/photos/ntd-gyeonggi-3.webp', '2026-10-20T14:25:00+09:00'::timestamptz, array['경기도','연천','연천쌀','쌀 수출','경기도주식회사']::text[], 'in_review'),
  ('gyeonggi', '경기도서관 ''책 만들기 프로그램'' 2기 출판기념회…도민 도서 38권 제작', '<p>@@BYLINE@@&nbsp;경기도서관은 19일 지하 1층 책공방에서 ''책 만들기 프로그램'' 2기 출판기념회를 열고 도민이 만든 도서 38권의 출판을 기념했다. 경기도는 20일 보도자료에서 이같이 밝혔다.</p><p>2기 참여자들은 지난 7월부터 9월까지 10주 동안 전문 강사의 지도를 받으며 글쓰기, 원고 수정, 표지 편집, 디자인 등 실제 도서 출판의 전 과정을 체험했다.</p><img src="/sites/newstoday/photos/ntd-gyeonggi-4.webp" alt="경기도서관 책공방에서 열린 &#x27;책 만들기 프로그램&#x27; 2기 출판기념회 현장. ⓒ경기도 (공공누리 제1유형)"><p><em>▲ 경기도서관 책공방에서 열린 ''책 만들기 프로그램'' 2기 출판기념회 현장. ⓒ경기도 (공공누리 제1유형)</em></p><p>완성된 도서는 시집 8권, 그림책 8권, 에세이 13권, 앨범책 9권 등 모두 38종이다. 경기도서관 안에서 누구나 읽을 수 있다.</p><p>경기도서관은 현재 ''책 만들기 프로그램'' 3기를 이어가고 있다. 프로그램 운영 장소인 책공방에서는 ''한 줄 쓰기 책갈피'', ''컬러링 엽서 제작'' 등 상시 체험 프로그램도 함께 운영한다.</p><p>윤명희 경기도서관장은 "개인의 삶과 경험들이 세상에서 유일한 한 권의 책으로 탄생해 모두와 함께할 수 있게 됐다는 점에서 뜻깊다"고 말했다. 윤 관장은 도민들이 도서관을 다양한 독서문화 활동이 이루어지는 공간으로 인식할 수 있도록 지원하겠다고 밝혔다.</p>', '경기도서관은 19일 지하 1층 책공방에서 ''책 만들기 프로그램'' 2기 출판기념회를 열고 도민이 만든 도서 38권의 출판을 기념했다. 완성된 책은 시집·그림책·에세이·앨범책 등으로, 도서관에서 누구나 읽을 수 있다.', '/sites/newstoday/photos/ntd-gyeonggi-4.webp', '2026-10-20T09:05:00+09:00'::timestamptz, array['경기도서관','책 만들기','출판기념회','도서관 프로그램','경기도']::text[], 'in_review'),
  ('gyeonggi', '경기경제청, 안산사이언스밸리서 일본기업 초청 현장 투자설명회', '<p>@@BYLINE@@&nbsp;경기경제자유구역청은 21일 안산사이언스밸리(ASV) 지구 일원에서 일본기업 대표와 투자 관계자를 초청해 현장 투자설명회를 열었다. 경기도는 같은 날 보도자료에서 이같이 밝혔다.</p><p>행사는 일본기업에 안산사이언스밸리 지구의 산·학·연 연구개발 인프라와 투자환경을 소개하기 위해 마련됐다. 인공지능·첨단로봇·스마트제조 등 미래 첨단산업 분야의 신규 투자수요를 발굴하고 한·일 기업 간 협력을 넓히는 것도 목적이다.</p><img src="/sites/newstoday/photos/ntd-gyeonggi-5.webp" alt="21일 열린 일본기업 초청 경기경제자유구역 ASV지구 현장 투자설명회 참석자들. ⓒ경기도 (공공누리 제1유형)"><p><em>▲ 21일 열린 일본기업 초청 경기경제자유구역 ASV지구 현장 투자설명회 참석자들. ⓒ경기도 (공공누리 제1유형)</em></p><p>경기경제자유구역청장과 안산시장, 한양대학교 관계자를 비롯해 서울재팬클럽(SJC)과 일본기업 등 투자 관계기관 관계자 17명이 참석했다. 행사는 한양대학교 에리카(ERICA) 캠퍼스에서 지구의 투자환경을 소개하는 설명회로 시작됐고, 안산시장이 지구 개발사업을 직접 브리핑했다.</p><p>오후에는 외국인 투자기업인 인테그리스코리아와 경기테크노파크 디지털전환허브(DX허브)를 방문했다. 참석자들은 스마트 데모공장과 제조데이터센터 등을 갖춘 DX허브의 제조혁신 지원시설을 살펴봤다.</p><p>안산사이언스밸리 지구는 안산시 상록구 사동 일원 약 1.66㎢(50만 평) 규모로 조성되는 첨단산업 거점이다. 한양대 에리카와 경기테크노파크, 한국생산기술연구원, 한국전기연구원, 한국산업기술시험원 등의 연구·시험인증 기관이 있으며, 인접한 반월·시화 국가산업단지와 연계할 수 있다고 경기경제청은 설명했다.</p><p>경기경제자유구역청장은 "이번 현장설명회가 일본기업들이 ASV지구의 우수한 연구개발 인프라와 투자 잠재력을 직접 확인하고, 새로운 사업 기회를 발굴하는 계기가 되길 바란다"고 말했다. 경기경제청은 후속 투자상담과 맞춤형 투자유치 활동을 이어갈 계획이다.</p>', '경기경제자유구역청은 21일 안산사이언스밸리 지구에서 일본기업 대표와 투자 관계자를 초청해 현장 투자설명회를 열었다. 한·일 기업 협력을 넓히고 인공지능·첨단로봇·스마트제조 분야 투자 수요 발굴이 목적이다.', '/sites/newstoday/photos/ntd-gyeonggi-5.webp', '2026-10-21T15:20:00+09:00'::timestamptz, array['경기경제자유구역청','안산사이언스밸리','투자설명회','일본기업','안산']::text[], 'in_review'),
  ('incheon', '인천시, 인천애뜰 공영주차장 요금 감면… 전기차 충전 27면 설치', '<p>@@BYLINE@@&nbsp;인천시가 인천애뜰 공영주차장의 주차요금을 감면하고, 시청 부설주차장에 전기차 충전시설 27면을 설치한다. 인천시는 22일 보도자료를 통해 시민의 주차 편의를 높이고 전기차 충전 수요에 대응하기 위한 조치라고 밝혔다.</p><p>시는 「인천광역시 주차장 설치 및 관리 조례」 개정에 따라 지난 10월 8일부터 인천애뜰 공영주차장 이용자에게 요금 감면을 적용하고 있다. 최초 1시간은 요금을 받지 않고, 이후 요금은 50%를 감면한다.</p><img src="/sites/newstoday/photos/ntd-incheon-1.webp" alt="인천애뜰 공영주차장 출입구 ⓒ인천시 (공공누리 제1유형)"><p><em>▲ 인천애뜰 공영주차장 출입구 ⓒ인천시 (공공누리 제1유형)</em></p><p>이에 따라 일반차량 기준 1일 최대 주차요금은 기존 6,000원에서 3,000원으로, 월 정기권 요금은 6만 원에서 3만 원으로 내려갔다. 시는 이용 부담을 줄이고 주차장 이용 효율을 높여 시청을 찾는 시민의 주차 편의를 개선하려는 것이라고 설명했다.</p><p>전기차 충전시설도 늘린다. 시는 인천애뜰공영주차장 준공에 따라 전기차 충전시설 의무 설치 기준을 반영하고, 친환경자동차 보급 확대에 따른 충전 인프라 수요에 대응하기 위해 시청 부설주차장 내 충전시설을 확대한다고 밝혔다.</p><p>충전시설은 시청 민원동 앞 13면, IDC동 앞 14면 등 모두 27면 규모다. 시는 충전시설의 화재 안전성을 고려해 모든 시설을 지상에 설치할 계획이며, 공사는 10월 말 마무리하고 11월 중 운영을 시작할 예정이다.</p><p>인천시 행정국장은 “이번 주차장 이용환경 개선과 전기차 충전시설 확충을 통해 시민들의 주차 부담을 줄이고 친환경차 이용 편의를 높이겠다”고 밝혔다. 앞으로도 공공시설 이용환경을 지속적으로 개선해 시민이 체감할 수 있는 행정서비스를 제공하겠다는 설명이다.</p>', '인천시가 10월 8일부터 인천애뜰 공영주차장 요금을 감면해 일반차량 1일 최대 요금을 6,000원에서 3,000원으로 낮췄다. 시청 부설주차장에는 전기차 충전시설 27면을 설치해 11월 중 운영할 계획이다.', '/sites/newstoday/photos/ntd-incheon-1.webp', '2026-10-22T07:11:00+09:00'::timestamptz, array['인천시','인천애뜰','공영주차장','주차요금','전기차충전']::text[], 'in_review'),
  ('incheon', '인천시, 영종~덕적 도심항공교통 실증 마쳐… 도서지역 공공수요 점검', '<p>@@BYLINE@@&nbsp;인천시가 10월 20일 영종도와 덕적도를 연결하는 노선에서 도서지역 공공수요 기반 도심항공교통(UAM) 실증을 마쳤다. 인천시는 21일 보도자료에서 항공우주산학융합원, K-UAM One TEAM과 함께 실증을 진행했다고 밝혔다.</p><p>실증은 ‘2026년 인천 도서지역 도심항공교통(UAM) 실증 지원사업’의 일환으로 추진됐다. 시는 내륙 의료기관 이용, 생활 서비스 접근, 긴급 이동 등 도서지역 특유의 공공수요를 고려해 공공형 UAM 서비스의 운용 가능성을 확인하는 데 중점을 뒀다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-incheon-2.webp" alt="10월 20일 인천 도서지역 UAM 실증에 참여한 관계자들이 대역기 헬기 앞에서 기념 촬영을 하고 있다. ⓒ인천시 (공공누리 제1유형)"><p><em>▲ 10월 20일 인천 도서지역 UAM 실증에 참여한 관계자들이 대역기 헬기 앞에서 기념 촬영을 하고 있다. ⓒ인천시 (공공누리 제1유형)</em></p><p>실증에는 항공우주산학융합원을 비롯해 KT, 대한항공, 현대건설, 현대자동차, 인천국제공항공사로 구성된 ‘K-UAM One Team’이 참여했다. 실제 비행은 영종도 거잠포·왕산마리나와 덕적도를 잇는 구간에서 UAM 대역기인 헬기를 활용해 이뤄졌다.</p><p>시는 노선을 설계할 때 공항 주변 공역과 기존 항공교통 흐름, 해상 비행 특성, 이착륙 여건을 종합적으로 고려했다고 밝혔다. 인천시 UAM 플랫폼과 국가연구개발과제로 개발된 UAM 교통관리시스템을 연계해 운항관리, 교통관리, 버티포트 운영, 통신 및 정보공유 기능도 점검했다.</p><p>시는 이번 실증이 도서지역의 공공수요 발굴부터 운항 노선 설계, 실제 비행 검증까지 국토교통부와 지자체, 민간 기업이 협력해 추진한 국내 최초 사례라고 설명했다. 지자체 차원에서 UAM 기술을 도서 주민의 실질적인 이동 편의와 연결할 수 있는 가능성을 확인했다는 평가도 내놓았다.</p><p>인천시는 현장에서 확인한 운항 조건과 개선사항을 바탕으로 노선 운영계획과 이착륙 인프라, 통신·교통관리체계, 안전관리 방안을 보완하고, 거잠포와 덕적도를 중심으로 버티포트 조성 및 기존 시설 활용 방안을 추진할 계획이다. 실증 결과는 국토교통부 도심항공교통 시범운용구역 지정 추진과 연계해 후속 실증과 단계적 서비스 도입 실행계획을 구체화하는 데 활용할 방침이다.</p><p>인천시 해양항공국장은 “이번 실증은 도심항공교통(UAM) 기술을 도서지역의 실제 교통수요와 연계해 공공서비스로 확장할 가능성을 확인했다는 데 의미가 있다”고 말했다. 이어 관계기관과 협력해 도서지역 주민의 교통 접근성과 이용 편의를 높이겠다고 덧붙였다.</p>', '인천시가 10월 20일 영종도와 덕적도를 잇는 노선에서 도서지역 공공수요 기반 도심항공교통(UAM) 실증을 마쳤다. 시는 보완 사항을 반영해 거잠포와 덕적도를 중심으로 버티포트 조성과 후속 실증을 추진할 계획이다.', '/sites/newstoday/photos/ntd-incheon-2.webp', '2026-10-21T09:30:00+09:00'::timestamptz, array['인천시','UAM','도심항공교통','영종도','덕적도']::text[], 'in_review'),
  ('incheon', '인천 선수단, 전국기능경기대회 종합 10위… 인천시 해단식 열어', '<p>@@BYLINE@@&nbsp;인천시가 제61회 전국기능경기대회에 참가한 인천 선수단의 해단식을 열었다. 인천시는 21일 쉐라톤 그랜드 인천 호텔에서 인천광역시기능경기위원회와 함께 ‘2026년 제61회 전국기능경기대회 인천광역시 선수단 해단식’을 개최했다고 밝혔다.</p><p>행사는 8월 22일부터 28일까지 7일간 열린 대회의 성과를 돌아보고, 우수한 성적을 거둔 선수들을 축하하며 선수 육성에 힘쓴 관계자들을 격려하기 위해 마련됐다. 해단식에는 입상 선수 42명과 지도교사, 해당 학교·기관장 등 120여 명이 참석했다.</p><img src="/sites/newstoday/photos/ntd-incheon-3.webp" alt="인천시 선수단 해단식 참석자들이 ‘2028 G20 정상회의는 인천에서’ 문구가 적힌 피켓을 들고 있다(G20 유치 기원 퍼포먼스). ⓒ인천시 (공공누리 제1유형)"><p><em>▲ 인천시 선수단 해단식 참석자들이 ‘2028 G20 정상회의는 인천에서’ 문구가 적힌 피켓을 들고 있다(G20 유치 기원 퍼포먼스). ⓒ인천시 (공공누리 제1유형)</em></p><p>16년 만에 인천에서 열린 이번 대회에 인천시 선수단은 37개 직종 101명이 출전했다. 25개 직종에서 금메달 2개, 은메달 4개, 동메달 10개, 우수상 2개, 장려상 23개 등 모두 41개의 상을 받았다.</p><p>이에 따라 인천시는 종합 순위 10위를 기록해 전년도 14위보다 4단계 올랐다. 시는 정보기술 직종에서 인천 대표 선수가 금·은·동메달을 모두 차지했다고 전했다.</p><p>대회 입상자는 해당 직종 산업기사 실기시험이 면제된다. 직종별 상위 득점자 2명(팀)은 국가대표 선발 평가 경기를 거쳐 ‘2028년 일본 아이치 국제기능올림픽대회’ 출전 자격을 얻는다.</p><p>시는 그동안 선수들의 경기력 향상을 위해 강화훈련비, 숙식비, 공구 수송비 등 제반 경비를 지원하고 안전관리를 해 왔다고 밝혔다. 인천시 경제국장은 “선수들이 우수한 기능 인재라는 긍지와 자부심을 갖고 숙련기술 연마에 지속해서 매진해 주길 바란다”고 말했다.</p>', '인천시가 10월 21일 제61회 전국기능경기대회 인천 선수단 해단식을 열었다. 인천 선수단은 25개 직종에서 41개의 상을 받아 종합 10위를 기록했으며, 이는 전년도 14위보다 4단계 오른 성적이다.', '/sites/newstoday/photos/ntd-incheon-3.webp', '2026-10-21T17:20:00+09:00'::timestamptz, array['인천시','전국기능경기대회','해단식','기능인재','인천선수단']::text[], 'in_review'),
  ('incheon', '송도에 글로벌 바이오 캠퍼스 실습교육장 개소… 백신 인력 양성', '<p>@@BYLINE@@&nbsp;인천경제자유구역청이 송도 연세대학교 국제캠퍼스에 중·저소득국의 백신·바이오의약품 생산인력을 양성하기 위한 ‘글로벌 바이오 캠퍼스 실습교육장’을 열었다. 인천시는 10월 20일 보도자료를 통해 이날 개소식이 열렸다고 밝혔다.</p><p>실습교육장은 2022년 2월 우리나라가 세계보건기구(WHO)로부터 ‘글로벌 바이오 인력양성 허브(GTH-B)’로 지정된 것을 계기로 송도에 구축한 전용 교육시설이다. 개소식에는 WHO 사무총장과 보건복지부 장관, 인천경제자유구역청장, 글로벌바이오인력양성허브 지원재단 이사장 등 관계자 30여 명이 참석했다.</p><img src="/sites/newstoday/photos/ntd-incheon-4.webp" alt="송도 글로벌 바이오 캠퍼스 실습교육장 개소식에서 참석자들이 테이프 커팅을 하고 있다. ⓒ인천시·인천경제청 (공공누리 제1유형)"><p><em>▲ 송도 글로벌 바이오 캠퍼스 실습교육장 개소식에서 참석자들이 테이프 커팅을 하고 있다. ⓒ인천시·인천경제청 (공공누리 제1유형)</em></p><p>시설은 연세대 국제캠퍼스 SL바이젠 산학협력관 2층에 있으며, 전체 면적은 약 2,492㎡(실습공간 약 1,719㎡)다. 미생물 배양·정제·분석과 품질관리(QA/QC) 교육을 위한 전문 실습실을 갖췄다.</p><p>인천경제청은 2028년까지 생산공정과 품질관리 분야 장비를 단계적으로 확충해 백신·바이오의약품 제조부터 품질관리까지 전 공정을 아우르는 실습교육 기반을 완비할 예정이라고 밝혔다. 경제청은 이번 개소로 이론교육과 현장 실습을 연계한 교육이 강화돼 교육생의 생산공정·품질관리 실무 역량이 높아질 것으로 기대했다.</p><p>GTH-B 사업은 송도에 있는 (재)글로벌바이오인력양성허브 지원재단이 교육훈련을 총괄한다. 재단은 국제백신연구소(IVI) 및 전국 5개 지역 네트워크 캠퍼스(송도·시흥·오송·안동·화순)와 협력해 이론과 실무 중심의 교육과정을 운영한다.</p><p>인천경제청은 교육훈련 운영을 위해 2024년부터 2028년까지 총 90억 원을 지원한다. 실습교육장 시설·장비 구축은 국비로 추진되고 있다.</p><p>김종철 인천경제자유구역청장은 “글로벌 바이오 캠퍼스 실습교육장 개소는 송도가 국제적인 바이오 인력양성 거점으로 도약하는 중요한 계기가 될 것”이라고 밝혔다. 이어 송도의 바이오 인프라를 바탕으로 국제협력 사업을 뒷받침하겠다고 덧붙였다.</p>', '인천경제자유구역청이 송도 연세대 국제캠퍼스에 중·저소득국의 백신·바이오의약품 생산인력 양성을 위한 실습교육장을 열었다. 전체 면적 약 2,492㎡ 규모로 2028년까지 장비를 단계적으로 확충할 예정이다.', '/sites/newstoday/photos/ntd-incheon-4.webp', '2026-10-20T16:45:00+09:00'::timestamptz, array['인천경제자유구역청','송도','바이오','WHO','인력양성']::text[], 'in_review'),
  ('incheon', '인천시, 옹진 대이작 해역에 어린 참담치 35만 마리 방류', '<p>@@BYLINE@@&nbsp;인천시 수산자원연구소가 10월 20일 옹진군 자월면 대이작 해역에 어린 참담치 35만 마리를 방류했다. 연구소는 지역 특산물인 참담치의 자원 회복과 어업인 소득 증대를 위한 것이라고 밝혔다.</p><p>방류한 어린 참담치는 올해 4월 건강한 어미에게서 수정란을 확보해 약 197일 동안 키운 것이다. 방류에 앞서 전염병 검사를 거쳐 건강한 종자로 판정받았고, 껍질 높이(각고) 0.5㎝ 이상의 우량한 치패로 구성됐다.</p><img src="/sites/newstoday/photos/ntd-incheon-5.webp" alt="인천시 수산자원연구소가 대이작 해역에 어린 참담치를 방류하고 있다. ⓒ인천시 (공공누리 제1유형)"><p><em>▲ 인천시 수산자원연구소가 대이작 해역에 어린 참담치를 방류하고 있다. ⓒ인천시 (공공누리 제1유형)</em></p><p>참담치는 우리나라 연안의 암반 해역에 붙어 사는 토종 홍합으로, 외래종인 지중해담치(진주담치)와 구별된다. 육질이 두껍고 단단하며 특유의 풍미를 지닌 고부가가치 수산물이라는 것이 연구소의 설명이다. 연구소는 성장 속도가 느리고 양식이 까다로워 자연 채취에 의존하는 만큼, 어린 참담치를 지속적으로 생산해 방류하는 것이 자원 회복의 중요한 기반이 된다고 밝혔다.</p><p>수산자원연구소는 국내 유일의 참담치 치패 생산·방류 기관으로, 2016년부터 참담치 인공종자 생산과 방류를 이어오고 있다. 앞으로 기후변화에 따른 참담치의 생태와 성장 특성을 연구하고 양식기술을 개발해 안정적인 수산자원 조성과 어업인 소득 증대를 도모할 계획이다.</p><p>인천시 농수산식품국장은 “이번 방류가 인천 해역의 참담치 자원 회복과 지역 특산 수산물의 가치를 높이는 계기가 되길 바란다”고 말했다. 이어 수산자원 조성과 관리에 힘써 지역 어업인의 안정적인 소득 기반을 마련하겠다고 덧붙였다.</p>', '인천시 수산자원연구소가 10월 20일 옹진군 자월면 대이작 해역에 어린 참담치 35만 마리를 방류했다. 연구소는 지역 특산물인 참담치의 자원 회복과 어업인 소득 증대를 위한 것이라고 밝혔다.', '/sites/newstoday/photos/ntd-incheon-5.webp', '2026-10-20T11:35:00+09:00'::timestamptz, array['인천시','옹진군','참담치','수산자원','대이작도']::text[], 'in_review'),
  ('gangwon', '강원도, 유엔해비타트와 지역개발 국제연수 개최… 3개국 16명 참가', '<p>@@BYLINE@@&nbsp;강원특별자치도가 유엔해비타트(UN-Habitat)와 함께 10월 20일부터 27일까지 8일간 강원특별자치도 국제도시훈련센터(IUTC)에서 「지역개발과 도시 인프라」 국제연수를 연다. 도는 22일 보도자료에서 이같이 밝혔다.</p><p>도는 이번 연수가 지역 여건과 수요를 반영한 지속가능한 지역개발 방안을 모색하고, 스마트 도시관리와 미래 교통체계, 재난안전 등 도시 발전에 필요한 정책·실행 역량을 강화하기 위해 마련됐다고 설명했다. 강원의 주요 정책과 발전 경험을 해외 지방정부와 공유하는 데도 의미가 있다고 밝혔다.</p><img src="/sites/newstoday/photos/ntd-gangwon-1.webp" alt="강원특별자치도 국제도시훈련센터에서 열린 「지역개발과 도시 인프라」 국제연수 입교식 사진 ⓒ강원특별자치도 (공공누리 제1유형)"><p><em>▲ 강원특별자치도 국제도시훈련센터에서 열린 「지역개발과 도시 인프라」 국제연수 입교식 사진 ⓒ강원특별자치도 (공공누리 제1유형)</em></p><p>연수에는 몽골, 필리핀, 베트남의 공무원 14명과 전문가 2명 등 모두 16명이 참가한다. 국가별로는 몽골 6명, 필리핀 5명, 베트남 5명이다. 참가자들은 우리나라의 경제발전과 지역개발 정책을 비롯해 인공지능(AI) 기술, 스마트 생태도시, 재난 및 안전관리, 신도시 개발과 도시 인프라 등을 배운다.</p><p>프로그램은 인공지능 기술과 스마트 생태도시, 재난·안전관리 및 도시 회복력, 스마트 도시관리 통합 솔루션, 컴팩트 시티와 미래 모빌리티 등의 이론 강의와 현장견학으로 구성된다. 현장견학으로는 강릉에서 열리는 ITS 세계총회에 참가해 자율주행·드론배송·로봇주차 등 미래 교통기술을 살펴본다. 강릉 메타버스 체험관과 태백 365세이프타운도 방문해 첨단 도시기술과 재난 대응·안전관리 사례를 체험한다.</p><p>도는 유엔해비타트와 2006년 협약을 맺고 세계 지방정부 가운데 유일하게 국제 연수기관을 운영하고 있다고 밝혔다. 2007년부터 아시아·태평양 지역 개발도상국의 지속 가능한 도시 발전을 위한 공적개발원조(ODA)를 19년째 이어오고 있다.</p><p>강원특별자치도 국제협력관은 “이번 연수가 강원의 지역개발과 도시관리 경험을 국제사회와 공유하고 여건에 맞는 실질적인 정책 해법을 찾는 계기가 되기를 기대한다”고 밝혔다. 앞으로도 강원의 정책경험을 확산하고 도시발전을 위한 국제협력을 강화하겠다는 입장이다.</p>', '강원특별자치도가 유엔해비타트와 함께 10월 20일부터 27일까지 국제도시훈련센터에서 「지역개발과 도시 인프라」 국제연수를 연다. 몽골·필리핀·베트남 공무원과 전문가 16명이 참가하며 강릉과 태백 현장견학도 포함된다.', '/sites/newstoday/photos/ntd-gangwon-1.webp', '2026-10-22T07:25:00+09:00'::timestamptz, array['강원특별자치도','유엔해비타트','국제연수','국제도시훈련센터','지역개발']::text[], 'in_review'),
  ('gangwon', '정선 민둥산 경험루트, 2026 GOOD DESIGN KOREA 대통령상 수상', '<p>@@BYLINE@@&nbsp;강원 정선군 민둥산을 소재로 한 공공환경 디자인 프로젝트가 ‘2026년 GOOD DESIGN KOREA’에서 최고상인 대통령상을 받았다. 강원디자인진흥원은 22일 보도자료에서 정선군과 협업해 개발한 ‘20만 평 억새평원, 압도적인 민둥산 경험루트’가 수상했다고 밝혔다.</p><p>이 상은 산업통상자원부와 한국디자인진흥원(KIDP)이 주관한다. 국무총리상에는 삼성전자의 ‘갤럭시 Z Fold8’과 현대자동차의 ‘모베드’가 각각 선정됐다. 상격심사는 지난 9월 17~18일 코리아디자인센터에서 진행됐다.</p><img src="/sites/newstoday/photos/ntd-gangwon-2.webp" alt="정선 민둥산 등산로에 적용된 브랜딩 디자인과 안내사인(강원디자인진흥원 제공 ‘민둥산 브랜딩 사진’) ⓒ강원디자인진흥원 (공공누리 제1유형)"><p><em>▲ 정선 민둥산 등산로에 적용된 브랜딩 디자인과 안내사인(강원디자인진흥원 제공 ‘민둥산 브랜딩 사진’) ⓒ강원디자인진흥원 (공공누리 제1유형)</em></p><p>수상작은 민둥산의 독특한 자연환경과 방문객이 장소를 경험하는 전 과정을 디자인으로 재해석한 장소 브랜딩 공공환경 디자인 프로젝트다. 2024년부터 추진돼 현재 3차에 걸쳐 사업을 확대·발전시켜 오고 있다.</p><p>진흥원은 민둥산의 능선과 억새, 카르스트 지형인 돌리네, 붉은 토양 등 고유의 자연적 특징을 ‘자연의 겹’이라는 개념으로 시각화했다고 밝혔다. 이를 등산로 안내사인과 마을 입구 조형물 등에 일관되게 적용했고, 장소의 가치를 알리는 브랜드 홍보관도 함께 운영하고 있다.</p><p>진흥원은 이 프로젝트가 방문객 경험의 질을 높여 관광객 증대와 지역경제 활성화를 이끌었고, 강원 지역이 직면한 인구소멸 문제를 공공디자인으로 극복하는 해법을 제시했다는 점에서 높은 평가를 받았다고 설명했다. 진흥원은 이 프로젝트가 단순한 환경 개선을 넘어 사회문제 해결 영역에서도 성과를 거뒀다고 밝혔다.</p><p>수상작은 11월 25일부터 29일까지 열리는 ‘DESIGN KOREA 2026’ 행사장에서 특별 전시되며, 시상식은 12월 초 열릴 예정이다. 진재한 강원디자인진흥원 원장은 “지자체와 전문 기관, 디자인 기업이 뜻을 모아 민둥산만의 독보적인 자연적 가치를 경험 중심의 디자인으로 풀어낸 성과”라고 말했다.</p>', '강원디자인진흥원이 정선군과 협업해 개발한 ‘20만 평 억새평원, 압도적인 민둥산 경험루트’가 2026 GOOD DESIGN KOREA 최고상인 대통령상을 받았다. 수상작은 11월 25일부터 특별 전시된다.', '/sites/newstoday/photos/ntd-gangwon-2.webp', '2026-10-22T07:42:00+09:00'::timestamptz, array['정선','민둥산','굿디자인코리아','대통령상','강원디자인진흥원']::text[], 'in_review'),
  ('gangwon', '강원도, 양구서 고병원성 AI 가상방역훈련… 100여 명 참여', '<p>@@BYLINE@@&nbsp;강원특별자치도는 10월 20일 양구군농업기술센터에서 양구군과 합동으로 ‘2026년 고병원성 조류인플루엔자(AI) 가상방역훈련’을 했다. 도는 21일 보도자료에서 겨울철 AI 발생 위험에 대비해 초동방역 대응체계를 점검하고 방역 유관기관 간 협력체계를 강화하기 위한 훈련이라고 밝혔다.</p><p>훈련에는 도와 양구군을 비롯해 가축위생방역지원본부, 강원대학교 수의과대학, 강원특별자치도수의사회, 농·축협, 생산자단체, 시군 방역담당 공무원 등 100여 명이 참석했다. 행사는 방역 결의대회, AI 방역 추진상황 보고, 가상방역 현장훈련, 방역 퍼포먼스 순으로 진행됐다.</p><img src="/sites/newstoday/photos/ntd-gangwon-3.webp" alt="10월 20일 양구에서 열린 ‘2026년 고병원성 조류인플루엔자(AI) 가상방역 현장훈련’ 방역 결의대회 기념촬영 ⓒ강원특별자치도 (공공누리 제1유형)"><p><em>▲ 10월 20일 양구에서 열린 ‘2026년 고병원성 조류인플루엔자(AI) 가상방역 현장훈련’ 방역 결의대회 기념촬영 ⓒ강원특별자치도 (공공누리 제1유형)</em></p><p>훈련은 양구읍 파로호 인근에서 주민이 야생조류 폐사체 2마리를 발견해 신고하고, 검사 결과 고병원성 AI 항원이 검출된 상황을 가정해 이뤄졌다. 양구군은 관내 25만 수 규모의 가금농장을 보호하기 위해 폐사체 발견지 반경 3km 이내 소규모 가금농가를 대상으로 수매·도태를 실시하는 것으로 가정했다. 초동방역팀 투입, 역학조사, 이동제한, 통제초소 운영, 살처분 및 소독 등 단계별 방역조치도 실제 상황처럼 시연했다.</p><p>도는 실제 발생 상황에 준한 훈련으로 기관 간 협업체계와 현장 대응능력을 종합적으로 점검했다고 밝혔다. 이를 통해 고병원성 AI 발생에 대비한 신속·정확한 방역 대응체계를 한층 높였다는 설명이다.</p><p>강원특별자치도 농정국장은 “고병원성 AI는 예방과 초동대응이 무엇보다 중요하다”며 철새도래기 차단방역에 총력을 기울이겠다고 밝혔다. 실제 발생 시에도 빈틈없는 방역체계를 가동할 수 있도록 대응 역량을 지속적으로 강화하겠다고 덧붙였다.</p>', '강원특별자치도가 10월 20일 양구군농업기술센터에서 양구군과 합동으로 고병원성 조류인플루엔자 가상방역훈련을 했다. 도와 시군, 방역 유관기관 관계자 등 100여 명이 참석해 단계별 방역조치를 시연했다.', '/sites/newstoday/photos/ntd-gangwon-3.webp', '2026-10-21T10:15:00+09:00'::timestamptz, array['강원특별자치도','양구군','조류인플루엔자','가상방역훈련','방역']::text[], 'in_review'),
  ('gangwon', '강원도, 신규공무원 통합돌봄 교육 실시… 시군 전담인력 배치 추진', '<p>@@BYLINE@@&nbsp;강원특별자치도가 도·시군 신규공무원을 대상으로 통합돌봄 기본교육을 하고 있다. 도는 16일 보도자료에서 10월 15일 강릉에서 신규공무원 200여 명을 대상으로 교육을 실시했다고 밝혔다.</p><p>교육은 10월 1일 고성을 시작으로 강릉(15일), 원주(22일), 홍천(29일) 등 4회에 걸쳐 도·시군 신규공무원 900여 명을 대상으로 진행된다. 통합돌봄 제도 전반을 소개해 신규공무원이 어느 부서에서 일하든 돌봄이 필요한 주민을 발견하고 연계할 수 있도록 하는 것이 목적이다.</p><img src="/sites/newstoday/photos/ntd-gangwon-4.webp" alt="신규공무원 통합돌봄 기본교육 현장(강원특별자치도 제공 ‘현장사진’) ⓒ강원특별자치도 (공공누리 제1유형)"><p><em>▲ 신규공무원 통합돌봄 기본교육 현장(강원특별자치도 제공 ‘현장사진’) ⓒ강원특별자치도 (공공누리 제1유형)</em></p><p>교육은 2025년 9월부터 통합돌봄 교육과정을 개발한 한림대학교가 맡았다. 통합돌봄 업무 이해와 사례 기반 학습 등 현장 실무에 필요한 내용을 중심으로 진행한다. 도는 11월 중 새로 배치될 통합돌봄 전담공무원을 대상으로 실무교육도 할 계획이다.</p><p>도내 18개 시군은 통합돌봄 전담공무원을 읍면동 등에 배치해 지원망을 갖출 예정이다. 도는 전담공무원이 돌봄이 필요한 주민을 찾아 의료·요양·돌봄 서비스를 연결하고 서비스가 잘 제공되는지 살피는 역할을 맡는다고 설명했다.</p><p>도는 도민이 여러 기관을 따로 찾아다니지 않아도 필요한 도움을 받을 수 있도록 돕겠다는 입장이다. 그동안 시군과 함께 전담공무원 배치를 준비해 왔으며, 앞으로도 시군과 긴밀히 협력할 계획이라고 밝혔다.</p><p>강원특별자치도 복지보건국장은 “금년이 통합돌봄의 원년인 만큼, 교육과 인력 배치 등 제도 안착 지원에 중점을 두고 있다”고 밝혔다. 통합돌봄을 정착시켜 도민이 살던 곳에서 계속 살아갈 수 있는 환경을 만들겠다는 입장이다.</p>', '강원특별자치도가 도·시군 신규공무원 900여 명을 대상으로 통합돌봄 기본교육을 4회에 걸쳐 진행한다. 10월 15일 강릉에서는 신규공무원 200여 명이 교육을 받았고, 도내 18개 시군은 전담공무원 배치를 준비하고 있다.', '/sites/newstoday/photos/ntd-gangwon-4.webp', '2026-10-16T10:50:00+09:00'::timestamptz, array['강원특별자치도','통합돌봄','신규공무원','한림대학교','돌봄서비스']::text[], 'in_review'),
  ('gangwon', '강원도, 의료관련감염 예방·관리 유공 질병관리청장 기관 표창', '<p>@@BYLINE@@&nbsp;강원특별자치도가 의료관련감염 예방·관리에 기여한 공로로 질병관리청장 기관 표창을 받았다. 도는 18일 보도자료에서 10월 16일 서울 엘타워 그레이스홀에서 열린 ‘2026 의료관련감염 예방관리 주간 포럼’에서 표창을 수상했다고 밝혔다.</p><p>이번 표창은 질병관리청이 의료관련감염 예방·관리 주간을 맞아 수여했다. 도는 전국 지방자치단체 중 유일하게 기관 표창을 받았다는 점에서 의미가 크다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-gangwon-5.webp" alt="‘2026 의료관련감염 예방관리 주간 포럼’에서 열린 유공자 표창 수상 사진 ⓒ강원특별자치도 (공공누리 제1유형)"><p><em>▲ ‘2026 의료관련감염 예방관리 주간 포럼’에서 열린 유공자 표창 수상 사진 ⓒ강원특별자치도 (공공누리 제1유형)</em></p><p>도는 도내 의료기관을 대상으로 감염관리 지도·점검을 실시했다. 다제내성균(CRE 등) 감시체계를 운영하고 의료기관 감염관리 실태조사를 추진하는 등 의료관련감염 예방·관리 역량 강화에 힘써 왔다고 밝혔다.</p><p>도는 이런 노력이 의료기관 내 감염 위험을 줄이고 도민이 안심하고 의료서비스를 이용할 수 있는 환경을 조성하는 데 기여했다고 설명했다. 도는 이번 표창이 의료기관 감염관리 강화 성과를 인정받은 것이라고 밝혔다.</p><p>강원특별자치도 감염병관리과장은 “이번 수상은 현장에서 감염관리에 힘써주신 도내 의료기관과 관계자 여러분의 노력 덕분”이라며, 다제내성균을 비롯한 의료관련감염 예방·관리 체계를 강화하겠다고 밝혔다. 이어 도민이 안심할 수 있는 의료환경을 조성하고 건강을 지키는 데 최선을 다하겠다고 덧붙였다.</p>', '강원특별자치도가 10월 16일 서울에서 열린 2026 의료관련감염 예방관리 주간 포럼에서 질병관리청장 기관 표창을 받았다. 도는 전국 지방자치단체 중 유일하게 기관 표창을 받았다고 설명했다.', '/sites/newstoday/photos/ntd-gangwon-5.webp', '2026-10-18T10:20:00+09:00'::timestamptz, array['강원특별자치도','의료관련감염','질병관리청','감염관리','표창']::text[], 'in_review'),
  ('chungcheong', '충남농업기술원, 멜론 유전자원 평가·재배 기술 연구 추진', '<p>@@BYLINE@@&nbsp;충청남도 농업기술원 과채연구소가 멜론 재배 농가의 안정적인 생산과 소득 향상을 위해 유전자원 특성 평가와 재배 기술, 육종 연구를 추진하고 있다. 충남도는 22일 보도자료에서 이번 연구가 국내 재배 환경에 맞는 우수 자원을 찾고, 품종별 특성을 재배 현장에서 살릴 수 있는 기술을 확립하는 데 초점을 두고 있다고 밝혔다.</p><p>유전자원 특성 평가는 신품종 육성의 기초 단계다. 연구소는 과실 크기와 모양, 과육색, 당도, 식감 등을 비교·분석해 육종에 활용할 우수 자원을 찾는다. 도는 자원별 식감과 향 등의 장점을 살리면서 국내 재배 환경에서도 안정적으로 생산할 수 있는 계통을 찾는 것이 중요하다고 설명했다.</p><img src="/sites/newstoday/photos/ntd-chungcheong-1.webp" alt="충남농업기술원 멜론 재배 포장(시설 내부) ⓒ충청남도 (공공누리 제1유형)"><p><em>▲ 충남농업기술원 멜론 재배 포장(시설 내부) ⓒ충청남도 (공공누리 제1유형)</em></p><p>선발한 계통은 재배 시기와 환경에 따른 생육 상태, 착과 특성, 과실 품질 등을 검토해 현장 활용 가능성을 평가한다. 품종의 장점이 실제 생산성과 농가 소득으로 이어지려면 재배 기술도 갖춰야 한다는 것이 도의 설명이다. 시험 포장에서 얻은 결과를 농가의 재배 경험과 비교하고 현장 적용성을 확인해 품종 특성에 맞는 재배 방법을 마련한다는 계획이다.</p><p>수출시장 진출과 관련해서는 생산 단계부터 해외 소비자의 선호와 시장별 요구사항을 고려해야 한다고 도는 밝혔다. 목표 시장이 선호하는 과실 크기와 식감, 포장 형태를 파악하고 수확 직후부터 저장·운송 이후까지 상품성이 유지되는지 확인하는 과정이 중요하다는 것이다. 수출 대상국의 검역·안전성 기준에 맞는 생산 관리와 선별·포장·보관·운송 체계를 갖추고 시험 수출로 현지 반응과 경제성을 검토할 필요도 있다고 덧붙였다.</p><p>도는 연구 성과를 농가 소득으로 연결하려면 생산자조직과 유통·수출업체, 행정 간 협력이 중요하다고 강조했다. 농가는 재배 과정에서 얻은 경험과 개선 의견을 공유하고, 유통·수출업체는 시장 요구를 생산 현장에 전달해 품종과 재배 기술의 활용도를 높일 수 있다는 설명이다.</p><p>과채연구소 연구사는 “품종과 재배 기술 연구의 궁극적인 목표는 농업인이 안정적으로 생산하고 노력에 걸맞은 소득을 얻도록 돕는 것”이라고 말했다. 이 연구사는 충남이 국내 대표 멜론 산지의 위상을 이어갈 수 있도록 현장에 도움이 되는 연구에 힘쓰겠다고 밝혔다.</p>', '충청남도 농업기술원 과채연구소가 멜론 재배 농가의 안정적인 생산과 소득 향상을 위해 유전자원 특성 평가와 재배 기술, 육종 연구를 추진하고 있다고 22일 밝혔다. 수출시장 진출 때 고려할 사항도 설명했다.', '/sites/newstoday/photos/ntd-chungcheong-1.webp', '2026-10-22T07:10:00+09:00'::timestamptz, array['충남','멜론','충청남도농업기술원','육종','농가소득']::text[], 'in_review'),
  ('chungcheong', '충남미술관 국제포럼 개최…‘대화하는 미술관’ 방향 논의', '<p>@@BYLINE@@&nbsp;충청남도는 21일 충남도서관 문화교육동에서 ‘2026 충남미술관 국제포럼’을 열고 지역사회와 소통하며 세계와 연결되는 미래 미술관의 역할과 발전 방향을 논의했다. 도는 22일 보도자료에서 이번 포럼이 2027년 준공을 목표로 건립 중인 충남미술관의 운영 철학과 미래 비전을 공유하기 위해 마련됐다고 밝혔다.</p><p>‘대화하는 미술관 : 작품・전시・배움・지역’을 주제로 열린 포럼에는 국내외 미술관 관계자와 문화예술 전문가, 예술가 등이 참여했다. 도에 따르면 미술관을 작품을 모아 전시하는 공간을 넘어 예술을 매개로 지역사회와 소통하고 다양한 세대와 문화가 교류하는 열린 공공문화공간으로 확장하는 방향이 집중적으로 논의됐다.</p><img src="/sites/newstoday/photos/ntd-chungcheong-2.webp" alt="‘2026 충남미술관 국제포럼’이 열린 행사장 모습 ⓒ충청남도 (공공누리 제1유형)"><p><em>▲ ‘2026 충남미술관 국제포럼’이 열린 행사장 모습 ⓒ충청남도 (공공누리 제1유형)</em></p><p>주요 논의 내용으로는 지역의 역사와 생태, 주민의 삶을 연결하는 지속가능한 지역 미술관의 역할이 꼽혔다. 다양한 참여자의 개별성을 존중하는 포용적 미술관 운영, 새로운 공공미술관의 소장품 수집 제안, 교육과 참여를 통한 사회적 역할 확대, 지역사회 협력과 국제교류 활성화 등도 논의 대상이었다.</p><p>프랑스 북부 덩케르크의 프락 그랑라주(FRAC Grand Large)와 영국 모던 아트 옥스퍼드(Modern Art Oxford) 등 해외 미술기관 관계자도 참여했다. 이들은 기관의 운영 사례와 실천 경험을 공유하고, 미술관의 미래 방향과 지역민과 조화롭게 구현할 수 있는 프로그램 운영 방향을 제안했다.</p><p>도는 포럼에서 제시된 전문가 의견을 충남미술관 개관 프로그램을 비롯한 전시·교육·연구 등 주요 사업계획에 반영할 계획이라고 밝혔다. 국내외 문화예술기관과 지속적으로 교류해 공동연구와 전시·교육 프로그램 등 협력사업을 발굴하고 국제 미술관 협력 네트워크를 넓힌다는 방침이다.</p><p>충남도 문화체육관광국장은 “이번 국제포럼은 충남미술관이 지향하는 공공성과 지역성, 국제적 연대의 가치를 함께 고민하고 공유하는 뜻깊은 자리였다”고 말했다. 충남미술관은 지역 미술의 역사와 가치를 재조명하는 한편 국내외 현대미술의 다양한 흐름을 소개하고, 전시·교육·연구·참여가 유기적으로 연결되는 복합문화공간으로 조성될 예정이다.</p>', '충청남도가 21일 충남도서관 문화교육동에서 ‘2026 충남미술관 국제포럼’을 열고 지역사회와 소통하며 세계와 연결되는 미래 미술관의 역할과 발전 방향을 논의했다. 도는 제시된 의견을 개관 프로그램에 반영할 계획이다.', '/sites/newstoday/photos/ntd-chungcheong-2.webp', '2026-10-22T07:14:00+09:00'::timestamptz, array['충남','충남미술관','국제포럼','미술관','문화예술']::text[], 'in_review'),
  ('chungcheong', '충북 진천군, 평생학습도시 지정 20주년 기념 컨퍼런스 개최', '<p>@@BYLINE@@&nbsp;충북 진천군은 21일 진천복합커뮤니티센터와 생거진천평생학습관에서 평생학습도시 지정 20주년 기념 컨퍼런스를 개최했다. 진천군은 보도자료에서 이 행사가 지난 20년간 진천군 평생학습의 성과를 공유하고 앞으로의 발전 방향을 모색하기 위해 마련됐다고 밝혔다.</p><p>‘평생학습으로 높이는 도시의 격, 배우는 도시에서 머무는 도시로’를 주제로 열린 행사는 진천군과 충북인재평생교육진흥원이 공동 주최하고 여가문화연구소가 진행했다. 군민과 관계기관 관계자, 충북 지역 평생학습 관계자 등 100여 명이 참석했다.</p><img src="/sites/newstoday/photos/ntd-chungcheong-3.webp" alt="진천군평생학습센터가 들어선 진천군립도서관 건물 전경(자료사진) ⓒ진천군 (공공누리 제3유형)"><p><em>▲ 진천군평생학습센터가 들어선 진천군립도서관 건물 전경(자료사진) ⓒ진천군 (공공누리 제3유형)</em></p><p>행사는 ‘평생학습도시 진천, 20년의 성장과 변화’를 주제로 한 성과 공유로 시작됐다. 참석자들은 군이 지난 20년간 구축한 평생학습 기반과 주요 성과를 살펴보고 변화의 의미를 되새겼다. 이어 진천군수가 기조 강연에서 발전 성과와 미래 군정 방향을 소개했고, 중앙대학교 명예교수는 평생학습이 도시의 격을 높이는 방안을 발표했다.</p><p>오후에는 클래식 축하공연에 이어 세 개의 주제별 세션이 진행됐다. 세션 주제는 AI 시대 평생학습으로 키우는 도시의 미래 역량, 평생학습이 바꾸는 일상과 삶의 질, 사람을 연결하고 머물게 하는 평생학습이었다. 전문가 발표와 토론에 이어 종합 토론에서는 진천군 평생학습의 향후 과제와 발전 방향에 관한 의견을 나눴다.</p><p>야외광장에는 비누·부채 만들기, 혈당 건강 교실, 귀 건강 확인, 타로, 심폐소생술 등 다양한 체험 부스가 마련됐다. 군은 군민들이 생활 속 평생학습을 직접 경험할 수 있도록 했다고 설명했다.</p><p>진천군수는 “지난 20년의 발전은 배움에 대한 열정이 높은 군민 여러분이 함께 이뤄낸 성과”라고 말했다. 이어 평생학습으로 군민의 일상과 삶의 질을 높이고 사람이 모이고 머무는 평생학습도시를 만들어 가겠다고 밝혔다.</p>', '충북 진천군이 21일 진천복합커뮤니티센터와 생거진천평생학습관에서 평생학습도시 지정 20주년 기념 컨퍼런스를 열고 지난 20년의 성과와 앞으로의 발전 방향을 논의했다. 행사에는 100여 명이 참석했다.', '/sites/newstoday/photos/ntd-chungcheong-3.webp', '2026-10-22T07:40:00+09:00'::timestamptz, array['진천군','충북','평생학습도시','평생학습','컨퍼런스']::text[], 'in_review'),
  ('chungcheong', '대전시 AI혁신전략위 2차 회의…3개 분야 87개 과제 논의', '<p>@@BYLINE@@&nbsp;대전시는 21일 ‘대전시 AI혁신전략위원회’ 제2차 회의를 열고 인공지능(AI) 혁신과제와 민선 9기 정책 방향을 논의했다. 시는 보도자료에서 이 회의에 시민서비스, 행정혁신, 산업육성 3개 분야 총 87개 과제가 상정됐다고 밝혔다.</p><p>시는 이 위원회를 인공지능 정책의 최상위 지휘본부라고 소개했다. 이날 회의에서는 전 부서와 유관기관이 협력해 발굴한 과제를 놓고 논의가 이뤄졌다.</p><img src="/sites/newstoday/photos/ntd-chungcheong-4.webp" alt="대전시청사 전경(자료사진) ⓒ대전광역시 (공공누리 제1유형, 위키미디어 공용)"><p><em>▲ 대전시청사 전경(자료사진) ⓒ대전광역시 (공공누리 제1유형, 위키미디어 공용)</em></p><p>이번 제2차 회의는 지난 9월 10일 위원회가 출범한 뒤 한 달여 동안 진행된 과제 발굴 결과를 점검하는 자리였다. 본청 전 부서와 사업소, 공사·공단, 출연기관이 자체적으로 발굴한 인공지능 혁신과제를 검토·보완해 사업의 실효성과 시민 체감도를 높이려는 취지라고 시는 설명했다.</p><p>분야별 상정 과제는 시민서비스 31건, 행정혁신 31건, 산업육성 25건이다. 세 분야를 합치면 모두 87개 과제다.</p><p>시민서비스 분야에는 ‘온통대전 2.0 AI 시민생활 플랫폼’ 구축 등이 포함됐다. 행정혁신 분야에는 지능형 업무관리플랫폼(온AI) 도입 등이, 산업육성 분야에는 방산 인공지능 전환(AX) 종합지원센터 조성 등이 들어 있다.</p>', '대전시가 21일 ‘AI혁신전략위원회’ 제2차 회의를 열고 시민서비스·행정혁신·산업육성 3개 분야 87개 인공지능 혁신과제와 민선 9기 정책 방향을 논의했다고 밝혔다. 위원회는 9월 10일 출범했다.', '/sites/newstoday/photos/ntd-chungcheong-4.webp', '2026-10-21T15:30:00+09:00'::timestamptz, array['대전','대전시','인공지능','AI혁신전략위원회','민선9기']::text[], 'in_review'),
  ('chungcheong', '세종시, 여성친화도시 3회 연속 지정…2016년 첫 지정 이후', '<p>@@BYLINE@@&nbsp;세종특별자치시가 성평등가족부 주관 2026년 여성친화도시 지정심사를 통과해 3회 연속 여성친화도시로 지정됐다. 세종시는 22일 보도자료를 통해 이같이 밝혔다.</p><p>여성친화도시는 여성과 남성의 평등한 정책 참여를 보장하고 여성의 역량 강화와 돌봄·안전 증진을 위해 노력하는 지방자치단체에 수여하는 인증 제도다. 성평등가족부가 5년 단위로 지정한다. 세종시는 2016년 처음 지정된 뒤 2021년 재지정됐고, 올해 세 번째 연속 지정을 받았다.</p><img src="/sites/newstoday/photos/ntd-chungcheong-5.webp" alt="세종특별자치시청 청사(자료사진) 사진=Minseong Kim/위키미디어 공용 (CC BY-SA 4.0)"><p><em>▲ 세종특별자치시청 청사(자료사진) 사진=Minseong Kim/위키미디어 공용 (CC BY-SA 4.0)</em></p><p>시는 그동안 성평등 정책 추진 기반 강화, 여성의 경제·사회 참여 확대, 시민참여 활성화, 돌봄 및 안전환경 조성 등 여러 분야에서 여성친화정책을 추진해 왔다고 설명했다.</p><p>세부 추진 내용으로는 5급 이상 여성 공무원 비율 확대와 성인지적 사전검토제 시행이 꼽혔다. 여성일자리협의체, 여성친화기업인증제, 직장맘지원센터 운영과 여성친화도시 시민참여단 활성화, 세종여성플라자 운영도 포함됐다.</p><p>시는 지난 10년간 꾸준히 추진한 여성친화정책의 성과를 인정받았다고 밝혔다. 이번 지정을 계기로 그동안의 성과를 발전시키고 생활밀착형 여성친화정책을 확대할 방침이다.</p><p>조상호 세종시장은 “시민의 목소리를 정책에 적극 반영해 누구나 평등하고 안전하게 살아갈 수 있는 여성친화도시 세종을 만들어 가겠다”고 말했다.</p>', '세종특별자치시가 성평등가족부 주관 2026년 여성친화도시 지정심사를 통과해 2016년 첫 지정, 2021년 재지정에 이어 3회 연속 여성친화도시로 지정됐다고 22일 밝혔다. 시는 생활밀착형 정책을 확대할 방침이다.', '/sites/newstoday/photos/ntd-chungcheong-5.webp', '2026-10-22T07:22:00+09:00'::timestamptz, array['세종','세종시','여성친화도시','성평등','성평등가족부']::text[], 'in_review'),
  ('yeongnam', '경북도, 자활사업 20개에 622억 원 지원…자활한마당 열려', '<p>@@BYLINE@@&nbsp;경상북도는 자활근로, 자활센터 운영지원, 자산형성지원, 자활기금 등 자활 관련 20개 사업에 약 622억 원을 지원하고 있다고 밝혔다. 도는 21일 보도자료에서 보건복지부 지역자활센터 성과평가에서 도내 19개소 가운데 11개소가 우수기관으로 선정됐다고 설명했다.</p><p>도는 20일 포항종합운동장 실내체육관에서 자활사업 참여자와 관계자 1,800여 명이 참석한 가운데 ‘2026년 경상북도 자활사업참여자 자활한마당’을 열었다. 행사는 ‘사회통합과 안전망 구현을 위한 힘찬 발걸음’을 표어로 자활 경험과 자립 의지를 나누는 자리로 마련됐다.</p><img src="/sites/newstoday/photos/ntd-yeongnam-1.webp" alt="‘2026년 경상북도 자활사업참여자 자활한마당’ 행사 무대 ⓒ경상북도 (공공누리 제3유형)"><p><em>▲ ‘2026년 경상북도 자활사업참여자 자활한마당’ 행사 무대 ⓒ경상북도 (공공누리 제3유형)</em></p><p>행사에서는 자활사업 유공자 시상과 자활사업 미래상 선포식이 이어졌다. 노래경연대회 입상자의 식전공연과 축하공연도 진행됐다. 자활생산품 전시와 자활 사진전, 수기공모전도 열려 참여자의 활동과 성과를 소개했다.</p><p>표창은 자활사업 활성화에 기여한 공무원, 자활센터 종사자, 모범 자활사업 참여자 등 51명이 받았다. 경상북도지사상 13명, 한국지역자활센터협회장상 19명, 경북지역자활센터협회장상 19명이다. 자활성공수기 우수자 4명과 자활사진공모 우수센터 4개소에도 시상했다.</p><p>사진 공모전은 예선을 통과한 작품 가운데 참여자의 2차 투표로 우수 작품 4점을 뽑았다. 도는 자활사업을 균형 있게 운영하고 실증 공간을 조성하기 위해 한국자활복지개발원의 경상북도 유치도 추진한다고 밝혔다.</p><p>경북도 복지건강국장은 “이번 자활한마당은 자활사업참여자들이 자립의 꿈을 향해 나아가는 데 힘을 보태고, 자립 의지를 북돋우는 뜻깊은 자리가 됐다”고 말했다. 이어 자활사업 참여자들의 경제적·사회적 자립을 위해 다양한 지원 정책을 능동적으로 추진하겠다고 밝혔다.</p>', '경상북도가 자활 관련 20개 사업에 약 622억 원을 지원하고 있다고 밝혔다. 도는 20일 포항종합운동장 실내체육관에서 자활사업 참여자 1,800여 명이 모인 자활한마당을 열었다.', '/sites/newstoday/photos/ntd-yeongnam-1.webp', '2026-10-21T14:10:00+09:00'::timestamptz, array['경북','자활사업','자활한마당','포항','저소득층']::text[], 'in_review'),
  ('yeongnam', '대구·경북 통합 지역성장펀드 출범…1,294억 원 규모', '<p>@@BYLINE@@&nbsp;경상북도와 대구광역시가 총 1,294억 원 규모의 ‘대구·경북 통합 지역성장펀드’를 출범하고 대경권 벤처 생태계 육성에 나섰다. 경북도는 21일 보도자료에서 펀드 결성식이 이날 대구 엑스코 동관 1층에서 열렸다고 밝혔다.</p><p>모펀드는 중소벤처기업부 모태펀드 750억 원과 지방자치단체 출자금 143억 원, 은행·기업·기관 자본 401억 원으로 구성됐다. 재원의 90%인 1,164억 원은 로컬창업과 혁신벤처펀드, 지역 액셀러레이터·벤처캐피털(AC/VC) 전용 펀드 등 블라인드 펀드에 출자한다. 나머지 130억 원은 프로젝트펀드 70억 원과 후속투자 60억 원에 투입한다.</p><img src="/sites/newstoday/photos/ntd-yeongnam-2.webp" alt="21일 대구 엑스코에서 열린 ‘대구-경북 통합 지역성장펀드 결성식’ 무대 ⓒ경상북도 (공공누리 제3유형)"><p><em>▲ 21일 대구 엑스코에서 열린 ‘대구-경북 통합 지역성장펀드 결성식’ 무대 ⓒ경상북도 (공공누리 제3유형)</em></p><p>양 지자체는 2,000억 원 이상 규모의 자펀드를 추가로 조성해 지역 유망 벤처기업의 성장자금 조달을 지원할 계획이다. 도는 최근 5년간 국내 벤처투자의 70% 이상이 수도권에 집중됐다며, 이번 펀드가 대구·경북의 첨단 미래산업과 창업기업에 투자 재원을 연결한다고 설명했다.</p><p>결성식 1부에서는 iM뱅크와 한국벤처투자(KVIC), 기술보증기금이 ‘대경권 벤처생태계 활성화 MOU’를 체결하고 펀드 결성 세레머니를 했다. 2부에서는 한국벤처투자가 지역성장펀드 운용 방향을 설명했고, 경북대학교가 대경권 창업생태계 현황 연구 결과를 발표했다. 이어 패널토론이 진행됐다.</p><p>결성식에는 이철우 경상북도지사, 추경호 대구광역시장, 노용석 중소벤처기업부 1차관, 김장호 구미시장 등 지자체·정부 관계자와 주요 출자기관 대표 등 70여 명이 참석했다.</p><p>이철우 경상북도지사는 환영사에서 “정부와 지방의 자금을 마중물 삼아 대구·경북에서 창업하고, 투자받고, 성장하는 선순환 구조의 성공 신화를 만들어가겠다”고 말했다.</p>', '경상북도와 대구광역시가 총 1,294억 원 규모의 ‘대구·경북 통합 지역성장펀드’를 출범하고 대경권 벤처 생태계 육성에 나섰다. 결성식은 21일 대구 엑스코에서 열렸고, 모펀드에는 중기부 모태펀드 750억 원이 포함됐다.', '/sites/newstoday/photos/ntd-yeongnam-2.webp', '2026-10-21T15:11:00+09:00'::timestamptz, array['대구','경북','지역성장펀드','벤처투자','대경권']::text[], 'in_review'),
  ('yeongnam', '울산시, 2035 도시재생전략계획 공고…활성화지역 71곳 지정', '<p>@@BYLINE@@&nbsp;울산시는 도시지역을 대상으로 ‘2035 울산광역시 도시재생전략계획’을 수립·공고하고 향후 10년간 도시재생의 방향을 제시했다고 22일 밝혔다. 계획은 3대 생활권과 33개 도시재생권역을 설정하고 71개 도시재생활성화지역을 지정했다.</p><p>이번 계획은 「도시재생 활성화 및 지원에 관한 특별법」 제12조에 따라 마련됐다. 시는 2021년 개정된 도시재생전략계획 수립 지침을 반영해 도시재생사업의 지속성을 높이고 정부 정책 변화에도 유연하게 대응하는 데 초점을 맞췄다고 설명했다.</p><p>인구사회, 산업경제, 물리환경 등 전반적인 현황 분석과 쇠퇴 진단 결과를 바탕으로 생활권과 권역을 나눴다. 북부생활권은 중구·동구·북구를 대상으로 15개 권역, 남부생활권은 남구와 울주군 일부 지역을 대상으로 14개 권역이다. 서부생활권은 울주군 일부 지역을 중심으로 4개 권역이 설정됐다.</p><img src="/sites/newstoday/photos/ntd-yeongnam-3.webp" alt="울산 중구 일대 전경(자료사진) ⓒ울산광역시 중구청 (공공누리 제1유형, 위키미디어 공용)"><p><em>▲ 울산 중구 일대 전경(자료사진) ⓒ울산광역시 중구청 (공공누리 제1유형, 위키미디어 공용)</em></p><p>지정된 71개 도시재생활성화지역은 기존 2025 전략계획의 69개소보다 2개소 늘었다. 전체 면적은 905만 1,052.3㎡다. 구군별로는 중구 17개소, 남구 17개소, 동구 12개소, 북구 14개소, 울주군 11개소다.</p><p>기존 2025 전략계획에서 지정된 지역 가운데 24개소는 유지, 29개소는 변경됐고 16개소는 해제됐다. 새로 지정된 곳은 18개소다.</p><p>전략계획의 상세한 내용은 10월 22일부터 11월 20일까지 울산시 도시경관과와 각 구군 도시재생 관련 부서에 요청해 열람할 수 있다.</p><p>울산시 관계자는 71개 도시재생활성화지역을 중심으로 구군별 도시재생활성화계획을 수립하고, 국토교통부 공모와 연계하는 등 “지속 가능한 도시재생을 추진해 나가겠다”고 밝혔다.</p>', '울산시가 ‘2035 울산광역시 도시재생전략계획’을 수립·공고하고 3대 생활권과 33개 도시재생권역을 설정했다. 71개 도시재생활성화지역도 지정했다고 22일 밝혔으며, 계획은 11월 20일까지 열람할 수 있다.', '/sites/newstoday/photos/ntd-yeongnam-3.webp', '2026-10-22T07:31:00+09:00'::timestamptz, array['울산','도시재생','도시재생전략계획','울산시','원도심']::text[], 'in_review'),
  ('yeongnam', '경남도, 낙동강수계 재생에너지 지원사업 49억 원 확보', '<p>@@BYLINE@@&nbsp;경상남도는 낙동강수계관리위원회가 추진한 ‘2027년도 낙동강수계 재생에너지 특별주민지원 공모사업’에서 5개 시군 13개 사업이 선정돼 총 49억 원의 사업비를 확보했다고 22일 밝혔다. 전체 사업비 100억 원의 49%로, 경남도는 참여 시도 중 가장 높은 비중이라고 설명했다.</p><p>이 사업은 상수원관리지역 등 각종 규제로 불편을 겪는 주민의 소득 증대와 생활환경 개선을 지원하기 위한 것으로, 「낙동강수계 물관리 및 주민지원 등에 관한 법률」에 근거한다. 2027년부터 햇빛소득마을 조성과 마을공동시설, 가구별 재생에너지 설비 지원 등 재생에너지 분야 사업이 새로 도입된다.</p><img src="/sites/newstoday/photos/ntd-yeongnam-4.webp" alt="경상남도청 본관(창원) 자료사진 ⓒ대한민국역사박물관 현대사아카이브 (공공누리 제1유형, 위키미디어 공용, 2016년 촬영)"><p><em>▲ 경상남도청 본관(창원) 자료사진 ⓒ대한민국역사박물관 현대사아카이브 (공공누리 제1유형, 위키미디어 공용, 2016년 촬영)</em></p><p>경남도는 이번 공모에서 시군별 사업계획 수립을 지원하고 선정위원회 심사에 대비한 맞춤형 대응을 추진했다고 밝혔다. 선정된 사업은 햇빛소득마을 조성, 마을공동시설 지원, 가구별 재생에너지 설비 지원 등 3개 분야다.</p><p>햇빛소득마을 조성은 마을 공공부지에 태양광발전시설을 설치하고 발전 수익을 주민과 공유하는 사업이다. 인구 감소와 고령화로 어려움을 겪는 농촌지역에 새로운 소득 기반을 마련하는 것이 목적이다. 도는 사천시 곤명면 25개 마을과 곤양면 흥사마을, 양산시 원동면 대리·선리·장선마을 등 5개 사업에 총 39억 7천만 원을 지원하며, 태양광 설치 규모는 총 3,100kW다.</p><p>마을공동시설 지원으로는 진주시 상수원지역 삼계마을 경로당에 3천만 원을 지원한다. 가구별 재생에너지 설비 지원에는 9억 원을 투입해 진주 13가구, 양산 14가구, 산청 20가구, 합천 108가구 등 모두 155가구에 가정용 태양광과 히트펌프 설치를 지원한다.</p><p>경남도 환경산림국장은 “재생에너지 확대를 통한 지역 주민의 소득과 복지를 높이는 동시에 탄소중립 실현에도 기여한다는 점에서 의미가 크다”고 말했다. 이어 시군 및 지역 주민과 협력해 지역 여건에 맞는 사업을 계속 발굴하겠다고 밝혔다.</p>', '경상남도가 2027년도 낙동강수계 재생에너지 특별주민지원 공모사업에서 5개 시군 13개 사업이 선정돼 49억 원을 확보했다고 22일 밝혔다. 전체 사업비 100억 원의 49%이며, 햇빛소득마을 조성에 39억 7천만 원이 배정됐다.', '/sites/newstoday/photos/ntd-yeongnam-4.webp', '2026-10-22T07:38:00+09:00'::timestamptz, array['경남','낙동강수계','재생에너지','햇빛소득마을','주민지원']::text[], 'in_review'),
  ('yeongnam', '경남 김해시, 거점소독시설 운영 강화…고병원성 AI 차단방역', '<p>@@BYLINE@@&nbsp;경남 김해시는 고병원성 조류인플루엔자(AI) 특별방역대책기간(10월~내년 2월)을 맞아 거점소독시설 운영을 강화하고 축산차량 소독과 차단방역을 통해 가축전염병 예방에 나서고 있다고 21일 밝혔다.</p><p>시는 거점소독시설이 축산차량 등을 소독해 가축전염병의 유입과 확산을 막는 주요 방역시설이라고 설명했다. 특히 겨울철 철새 도래 시기에는 고병원성 AI 유입 위험이 높아지는 만큼 시설의 역할이 더 중요해진다는 것이다.</p><img src="/sites/newstoday/photos/ntd-yeongnam-5.webp" alt="거점소독시설 외관(보도자료 제공 사진) ⓒ김해시 (공공누리 제1유형)"><p><em>▲ 거점소독시설 외관(보도자료 제공 사진) ⓒ김해시 (공공누리 제1유형)</em></p><p>시는 10월 1일부터 한림면 거점소독시설을 운영하고 있고, 19일부터는 주촌면 거점소독시설을 시범운영하고 있다. 한림 시설은 18시간 관리인력을 배치해 운영하고, 주촌 시설은 24시간 무인으로 운영한다. 두 시설은 특별방역대책기간에 맞춰 내년 2월 28일까지 운영된다.</p><p>주촌 시설 시범운영은 축산차량의 소독 편의성을 높이고 시간 제약 없이 시설을 이용할 수 있는 운영체계를 마련하기 위한 것이다. 시는 시범운영 기간 시설 운영의 안정성과 이용 편의성 등을 점검하고, 결과를 토대로 특별방역대책기간이 끝난 뒤 상시 무인운영 여부를 검토할 계획이다.</p><p>시는 앞서 가금 관련 농장과 축산시설을 방문하는 축산차량이 방문 전 거점소독시설에서 소독을 받고 소독필증을 발급받도록 하는 행정명령을 시행했다. 이에 따라 축산차량의 소유자와 운전자는 행정명령을 지켜야 하고, 가금 관련 농장과 축산시설은 차량의 소독필증 발급 여부를 확인해야 한다.</p><p>김해시 축산과장은 “겨울철 고병원성 조류인플루엔자 예방을 위해 축산차량 운전자들의 적극적인 방역 참여가 중요하다”고 말했다. 시는 축산 관계자들에게 방역 수칙 준수에 적극 협조해 달라고 당부했다.</p>', '경남 김해시가 고병원성 AI 특별방역대책기간을 맞아 거점소독시설 운영을 강화했다. 한림면 시설은 관리인력을, 주촌면 시설은 24시간 무인 방식으로 시범 운영하며 두 시설은 내년 2월 28일까지 운영된다.', '/sites/newstoday/photos/ntd-yeongnam-5.webp', '2026-10-21T17:00:00+09:00'::timestamptz, array['김해시','경남','고병원성AI','거점소독시설','방역']::text[], 'in_review'),
  ('honam', '영암·강진 걸친 월출산 일원, 국가지정 명승으로 지정', '<p>@@BYLINE@@&nbsp;국가유산청은 16일 보도자료를 통해 전남광주통합특별시 영암군과 강진군에 걸친 「월출산 일원」을 국가지정자연유산 명승으로 지정한다고 밝혔다. 화강암 산악경관 위에 국가 제의와 불교문화, 시문과 옛 기록이 오랫동안 쌓인 복합적 산악 문화경관이라는 점이 지정 사유로 제시됐다.</p><p>지정 구역은 영암군 영암읍과 군서면, 강진군 성전면 일원의 71필지, 2,256,208㎡다. 관리단체는 전남광주통합특별시와 강진군, 영암군이다.</p><img src="/sites/newstoday/photos/ntd-honam-1.webp" alt="월출산의 암봉 경관. ⓒ국가유산청 (공공누리 제1유형)"><p><em>▲ 월출산의 암봉 경관. ⓒ국가유산청 (공공누리 제1유형)</em></p><p>국가유산청에 따르면 월출산은 「삼국사기」에 월나군, 곧 현재의 영암군에 있는 ‘월내악’이라는 이름으로 처음 기록됐다. 천황봉은 통일신라 시기부터 나라의 제사를 지낸 곳으로, 산악신앙과 국가 의례의 전통이 이어진 영산으로 소개됐다. 고려부터 조선까지는 서남부 불교문화의 중심지로 자리 잡았다고 국가유산청은 설명했다.</p><p>산 안에 있는 사찰도 지정 근거에 포함됐다. 무위사는 선종사찰의 전통과 조선 전기 왕실 후원으로 조성된 극락보전과 벽화를 간직한 곳이고, 도갑사는 통일신라 때 도선국사가 창건한 절로 왕실 불교와 지역 사찰의 관계를 보여준다고 국가유산청은 밝혔다.</p><p>자연경관과 생태적 가치도 거론됐다. 월출산은 평야에서 급격히 솟은 독립 화강암 산괴로, 돔형 암봉과 성곽형 암릉 같은 화강암 풍화 지형이 발달했다. 벌레를 잡아먹는 식충식물 등 특이 식생이 분포해 생태학적 가치가 높다고 국가유산청은 덧붙였다.</p><p>이 밖에 구정봉의 아홉 개 우물과 얽힌 설화, 시대별로 달리 불린 ‘월내악’ ‘소금강’ ‘천불’ 등의 이름, 정약용과 김창협 등이 남긴 유산기와 시문도 가치를 뒷받침하는 자료로 꼽혔다. 국가유산청은 후속 연구를 바탕으로 체계적으로 보존·관리하고, 국민이 가치를 직접 체험할 수 있는 활용 방안도 마련하겠다고 밝혔다.</p>', '국가유산청이 전남광주통합특별시 영암군과 강진군에 걸쳐 있는 월출산 일원을 국가지정자연유산 명승으로 지정한다고 16일 밝혔다. 지정 구역은 71필지 2,256,208㎡이며, 역사와 종교, 지질 가치가 지정 사유로 제시됐다.', '/sites/newstoday/photos/ntd-honam-1.webp', '2026-10-16T10:12:00+09:00'::timestamptz, array['월출산','명승','국가유산청','영암','강진']::text[], 'in_review'),
  ('honam', '전북 완주 전주천 상죽음보 철거 협약…내년 1월 착공', '<p>@@BYLINE@@&nbsp;기후에너지환경부는 19일 보도자료에서 전북 완주군 상관면 전주천 상죽음보 현장에서 ‘전주천 작은 보 철거사업 공동이행 협약’을 체결한다고 밝혔다. 협약에는 환경부 외에 전북특별자치도, 완주군, 재단법인 숲과나눔, 한국 코카-콜라 유한회사, 전북환경운동연합, 한국환경공단 등 7개 기관이 참여한다.</p><p>상죽음보는 하천 바닥을 유지하려고 1970년대 중반 설치된 낙차보다. 단면 기준 길이는 5.9m, 높이는 2.2m라고 환경부는 설명했다. 보로 막힌 물길을 이어 수생태계의 연속성과 하천의 자연성을 되찾는 것이 사업 목적이다.</p><img src="/sites/newstoday/photos/ntd-honam-2.webp" alt="철거 대상인 전주천 상죽음보 일대 전경(전북 완주군 상관면). ⓒ기후에너지환경부 (공공누리 제1유형)"><p><em>▲ 철거 대상인 전주천 상죽음보 일대 전경(전북 완주군 상관면). ⓒ기후에너지환경부 (공공누리 제1유형)</em></p><p>철거 사업비는 약 3억 원으로, 글로벌 코카-콜라 재단의 후원으로 마련된다. 코카-콜라가 숲과나눔에 사업비를 후원하면 숲과나눔이 철거 사업을 추진하는 구조다. 공사는 내년 1월 시작해 4월에 마무리된다.</p><p>기관별 역할도 나뉘었다. 환경부와 전북지방환경청, 전북특별자치도, 완주군은 사업 추진에 필요한 행정적 지원을, 한국환경공단은 기술 지원을 맡는다. 전북환경운동연합은 사업의 취지와 성과를 지역사회에 알리고 참여를 넓히는 역할을 한다.</p><p>환경부는 시민사회가 제안한 보 철거 사업을 기업 후원으로 추진하고 중앙정부와 지방정부, 공공기관이 행정·기술로 뒷받침하는 민관협력 방식이라는 점에 의미를 뒀다. 일반적으로 하천의 보는 물의 흐름과 물고기 등 수생생물의 이동에 영향을 준다고 환경부는 설명했다.</p><p>김성환 기후에너지환경부 장관은 “이번 협약은 국민이 바라는 하천의 변화를 기업의 후원과 민관의 협력으로 실현하는 뜻깊은 출발점”이라고 밝혔다. 환경부는 이번 경험을 바탕으로 이런 협력 방식이 전국 다른 하천으로 확산되도록 지원하겠다는 계획이다.</p>', '기후에너지환경부와 전북특별자치도, 완주군 등 7개 기관이 19일 전주천 상류 상죽음보 철거를 위한 공동이행 협약을 체결한다. 사업비는 약 3억 원이며 철거는 내년 4월 끝날 예정이다.', '/sites/newstoday/photos/ntd-honam-2.webp', '2026-10-19T13:05:00+09:00'::timestamptz, array['전주천','보 철거','완주군','기후에너지환경부','수생태계']::text[], 'in_review'),
  ('honam', '전남 순천만 야생조류 분변서 고병원성 AI 검출…위기경보 심각', '<p>@@BYLINE@@&nbsp;농림축산식품부와 기후에너지환경부는 20일 보도참고자료에서 전남광주통합특별시 순천시 순천만의 야생조류 분변에서 H5형 고병원성 조류인플루엔자(AI) 바이러스가 검출됐다고 밝혔다. 시료는 지난 12일 순천만에서 채취했고, 국립야생동물질병관리원이 정밀검사를 거쳐 20일 최종 확인했다.</p><p>이번 겨울철새 도래 이후 국내 야생조류에서 고병원성 AI가 확인된 것은 처음이다. 정부는 이날 전국 위기경보를 ‘주의’에서 ‘심각’으로 올리고 범정부 중앙사고수습본부를 가동했다. 전국 모든 지방정부에는 대책본부 상황실이 설치돼 24시간 비상 대응 체제로 바뀌었다.</p><img src="/sites/newstoday/photos/ntd-honam-3.webp" alt="순천만 갈대밭 일대(자료사진). 촬영 Chicant22, 출처 Wikimedia Commons (CC BY-SA 3.0)"><p><em>▲ 순천만 갈대밭 일대(자료사진). 촬영 Chicant22, 출처 Wikimedia Commons (CC BY-SA 3.0)</em></p><p>정부는 검출 지점 반경 10km 이내를 중심으로 야생조류 폐사체 수색과 철새 정밀조사를 벌이고, 지방정부에 현장 소독과 출입통제를 요청했다. 반경 10km 안에서 사육 중인 가금류에는 이동통제와 정밀검사, 전화예찰을 실시한다. 순천만 수변 3km 이내는 특별관리지역으로 지정해 사람과 차량 출입을 통제한다.</p><p>전국 가금농장과 축산 관련 시설은 앞으로 일주일을 일제 소독주간으로 정해 집중 소독한다. 바이러스의 N형은 염기서열 분석 등 정밀검사로 확인하며 3~5일이 걸릴 예정이라고 정부는 밝혔다.</p><p>정부는 시민들에게 철새가 많이 모이는 하천과 저수지, 갯벌 등 철새도래지 방문을 가급적 자제해 달라고 안내했다. 불가피하게 방문하면 야생조류와 접촉하지 않고 신발과 차량을 소독하며 귀가 후 손을 씻어야 한다. 폐사체나 이상 행동을 보이는 새를 발견하면 만지거나 옮기지 말고 관할 지방정부나 국립야생동물질병관리원에 신고하라고 당부했다.</p><p>가금농장 관계자에게는 외부인과 차량 출입을 막고 농장 안팎을 매일 소독하라고 요청했다. 가금이 평소보다 많이 죽거나 알을 덜 낳는 등 의심 증상이 있으면 즉시 방역당국에 신고해야 한다. 이동식 농식품부 방역정책국장은 “야생조류에서 고병원성 AI가 확인되면서 농장에서 고병원성 AI가 발생할 위험이 커진 상황”이라고 밝혔다.</p>', '농림축산식품부와 기후에너지환경부는 순천만 야생조류 분변에서 H5형 고병원성 AI가 검출돼 전국 위기경보를 심각으로 올렸다고 20일 밝혔다. 철새도래지 방문 자제와 폐사체 신고를 당부했다.', '/sites/newstoday/photos/ntd-honam-3.webp', '2026-10-20T15:20:00+09:00'::timestamptz, array['순천만','고병원성 AI','조류인플루엔자','위기경보','방역']::text[], 'in_review'),
  ('honam', '국립나주병원, 23일 광주 문화전당서 정신건강 공감 콘서트', '<p>@@BYLINE@@&nbsp;국립나주병원은 정신건강의 날을 기념해 10월 23일 광주 국립아시아문화전당에서 ‘2026 마음을 잇는 공감 콘서트’를 개최한다. 병원은 16일 배포한 보도참고자료에서 문화예술을 통해 정신건강에 대한 긍정적 인식을 넓히려는 취지라고 밝혔다.</p><p>행사는 세 부분으로 짜였다. 먼저 한양대학교병원 정신건강의학과 교수가 ‘스트레스 관리를 통한 뇌 건강 지키기’를 주제로 특강을 한다. 이어 조현병 당사자가 자신의 인생과 회복 이야기를 들려준다.</p><img src="/sites/newstoday/photos/ntd-honam-4.webp" alt="행사가 열리는 국립아시아문화전당이 있는 광주 도심 전경(자료사진). 촬영 Lain4lest, 출처 Wikimedia Commons (CC BY-SA 3.0)"><p><em>▲ 행사가 열리는 국립아시아문화전당이 있는 광주 도심 전경(자료사진). 촬영 Lain4lest, 출처 Wikimedia Commons (CC BY-SA 3.0)</em></p><p>마지막 순서로 포레스트 앙상블과 광주챔버싱어즈가 ‘마음을 울리는 하모니’ 무대를 꾸며 음악으로 서로의 마음을 잇는 시간을 갖는다. 병원은 국립아시아문화전당과 협력해 문화 공간에서 정신건강 증진 사업에 참여할 기회를 넓힌다는 점도 의미로 꼽았다.</p><p>병원은 스트레스와 우울 등 정신건강 문제에 대한 사회적 관심과 대응 필요성이 커지는 상황에서 이번 행사를 마련했다고 설명했다. 정신건강을 무겁게만 받아들이기보다 자연스럽게 마음을 돌보는 계기를 제공하고, 누구나 부담 없이 정신건강서비스를 이용할 수 있도록 하겠다는 뜻이다.</p><p>참여 신청은 안내 포스터 하단의 QR코드를 스캔하거나 국립나주병원 누리집을 통해 할 수 있다고 병원은 안내했다. 시영화 국립나주병원장은 “이번 공감 콘서트가 일상에서 잠시 멈춰 자신의 마음을 돌아보고 서로의 마음을 잇는 따듯한 시간이자 정신건강에 대한 관심과 이해를 높이는 계기가 되기를 바란다”고 밝혔다.</p>', '국립나주병원이 정신건강의 날을 맞아 23일 광주 국립아시아문화전당에서 ‘2026 마음을 잇는 공감 콘서트’를 연다고 밝혔다. 스트레스 관리 특강과 회복 이야기, 음악 공연으로 구성된다.', '/sites/newstoday/photos/ntd-honam-4.webp', '2026-10-16T14:34:00+09:00'::timestamptz, array['국립나주병원','정신건강','공감 콘서트','국립아시아문화전당','광주']::text[], 'in_review'),
  ('honam', '외교부 공공외교대사, 전주대 한식조리학과 찾아 청년과 소통', '<p>@@BYLINE@@&nbsp;외교부는 16일 보도자료에서 공공외교대사가 이날 전북 전주시를 찾아 전주대 한식조리학과 학생들을 만났다고 밝혔다. 외교부가 진행 중인 2026 디지털 글로벌 캠페인 ‘YouthFULL Tomorrow’의 현장 활동(아웃리치)이다.</p><p>‘YouthFULL Tomorrow’는 청년(Youth)과 가득함(Full)을 합친 이름으로, 청년들이 만들어 가는 미래를 뜻한다고 외교부는 설명했다. 공공외교대사는 학생들의 한식 연회 실습 과정을 지켜보고 한식 셰프로서의 포부와 해외 진출에 대한 관심을 들었다.</p><img src="/sites/newstoday/photos/ntd-honam-5.webp" alt="외교부 공공외교대사의 전주대 한식조리학과 방문 때 찍은 단체 사진. ⓒ외교부 (공공누리 제1유형)"><p><em>▲ 외교부 공공외교대사의 전주대 한식조리학과 방문 때 찍은 단체 사진. ⓒ외교부 (공공누리 제1유형)</em></p><p>대사는 미래 K-푸드의 주역으로 성장할 청년들을 격려하며 한식으로 세계에 한국을 알리는 ‘한식 외교관’ 역할을 해 달라고 당부했다. 참석한 학생 한 명은 “재외공관 관저요리사 등 해외 취업에 관심이 많았는데, 꿈에 한층 더 가까워진 것 같다”고 말했다고 외교부는 전했다.</p><p>이어 대사는 지난 9월 개관한 전주 아세안홀을 찾았다. 한-아세안센터 관계자에게는 전통과 문화의 도시 전주에 마련된 아세안홀을 통해 한국과 아세안 사이의 문화교류가 활발해지길 기대한다는 뜻을 전했다.</p><p>외교부는 지난 4월 이 캠페인을 시작한 뒤 고려대 축제 계기 홍보부스 운영(5월 21일), 전남대 방문(7월 9일), 한양대 방문(9월 15일) 등 국내 대학을 찾아 청년 밀착형 공공외교 활동을 이어왔다고 밝혔다. 외교부는 앞으로 캠페인에 청년 참여를 이끌어내고, 외교부 공공외교 SNS 채널 ‘KOREAZ’를 통해 지방도시의 매력을 해외 대중에게 소개하는 콘텐츠를 계속 제작할 방침이다.</p>', '외교부 공공외교대사가 16일 전북 전주를 찾아 전주대 한식조리학과 학생들을 만나고 지난 9월 개관한 전주 아세안홀을 방문했다. 외교부가 청년을 대상으로 진행 중인 디지털 글로벌 캠페인 활동의 하나다.', '/sites/newstoday/photos/ntd-honam-5.webp', '2026-10-16T16:47:00+09:00'::timestamptz, array['전주','외교부','공공외교','전주대','아세안홀']::text[], 'in_review'),
  ('jeju', '제주 저지곶자왈서 주민과 칡 제거…국립산림과학원 3km 정화', '<p>@@BYLINE@@&nbsp;산림청 국립산림과학원은 21일 보도자료에서 지난 16일 제주시 한경면 저지곶자왈 일대에서 저지마을 주민들과 함께 칡 제거와 지역 환경정화 활동을 했다고 밝혔다. 곶자왈 산림생태계를 보전하고 주민 생활환경을 개선하려고 난대·아열대산림연구소가 마련한 행사다.</p><p>연구소는 최근 기후변화의 영향으로 제주에 퍼지고 있는 칡이 숲 생태계를 어지럽히고 있다고 설명했다. 주민 생활공간까지 번지고 있어 관리가 필요한 상황이라는 것이다.</p><img src="/sites/newstoday/photos/ntd-jeju-1.webp" alt="제주시 한경면 저지곶자왈 일대에서 환경정화 활동에 나선 참가자들. ⓒ산림청 국립산림과학원 (공공누리 제1유형)"><p><em>▲ 제주시 한경면 저지곶자왈 일대에서 환경정화 활동에 나선 참가자들. ⓒ산림청 국립산림과학원 (공공누리 제1유형)</em></p><p>이날 연구소 직원과 마을 주민들은 저지리 일대 약 3km 구간에서 칡을 걷어내고 주변 환경을 정비했다. 국립산림과학원은 연구소와 지역 주민이 산림생태계 보전과 생활환경 개선에 함께 나섰다는 데 의미가 있다고 밝혔다.</p><p>연구소는 올봄에도 기업, 지역 마을회와 함께 자생수종 나무심기 행사를 진행한 바 있다. 봄철 나무심기에 이어 이번에는 칡 제거와 환경정화로 활동 범위를 넓힌 셈이다.</p><p>연구소 관계자는 “앞으로도 지속적인 곶자왈 산림생태계 보전 활동을 통해 마을 주민과 소통하고 상생하는 산림관리 체계를 만들어 나가겠다”고 밝혔다. 연구소는 이런 활동으로 지역사회와 함께 건강한 숲을 가꾸는 노력을 이어가고 있다고 설명했다.</p>', '산림청 국립산림과학원이 지난 16일 제주시 한경면 저지곶자왈 일대에서 저지마을 주민들과 함께 칡을 제거하고 환경정화 활동을 벌였다고 21일 밝혔다. 활동은 저지리 일대 약 3km 구간에서 진행됐다.', '/sites/newstoday/photos/ntd-jeju-1.webp', '2026-10-21T11:08:00+09:00'::timestamptz, array['곶자왈','제주','칡 제거','국립산림과학원','저지마을']::text[], 'in_review'),
  ('jeju', '제주서 배우고 취업까지…재외동포청·제주한라대 업무협약', '<p>@@BYLINE@@&nbsp;재외동포청은 18일 보도자료에서 지난 17일 제주한라대학교와 ‘재외동포 청년 인재 유치·양성 및 지역 정착을 위한 업무협약’을 체결했다고 밝혔다. 재외동포 청년들이 제주에서 전문 교육을 받고 지역 기업에 취업할 기회를 넓히는 것이 목적이다.</p><p>두 기관은 제주 산업 수요에 맞는 전문 교육과정을 운영하고, 현장실습과 인턴십을 통해 취업과 창업으로 이어지는 협력 체계를 마련하기로 했다. 제주한라대는 맞춤형 교육과정을 확대하고 지역 기업과의 연계를 강화한다.</p><img src="/sites/newstoday/photos/ntd-jeju-2.webp" alt="재외동포청과 제주한라대학교의 업무협약식 기념 촬영. ⓒ재외동포청 (공공누리 제1유형)"><p><em>▲ 재외동포청과 제주한라대학교의 업무협약식 기념 촬영. ⓒ재외동포청 (공공누리 제1유형)</em></p><p>재외동포청은 해외 인재 유치와 홍보, 지역사회 적응을 위해 협력한다. 재외동포청은 협약식에 앞서 제주에 사는 동포와 관련 단체 관계자들과 간담회도 열어 생활 현장의 어려움을 들었다고 밝혔다.</p><p>간담회 참석자들은 자녀 교육과 일자리, 의료서비스 이용 등 일상에서 겪는 불편을 전했다. 관련 제도 개선도 건의했다고 재외동포청은 전했다.</p><p>김경협 재외동포청장은 “재외동포 청년의 국내 정착은 지역사회에도 새로운 활력이 될 수 있다”고 말했다. 청장은 지역 대학과 기업 협력을 넓혀 청년에게는 새로운 기회를, 지역에는 필요한 인재를 연결하겠다고 밝혔다.</p>', '재외동포청이 17일 제주한라대학교와 재외동포 청년 인재 유치·양성 및 지역 정착을 위한 업무협약을 체결했다. 맞춤형 교육과정과 현장실습, 인턴십으로 취업·창업을 연계한다는 계획이다.', '/sites/newstoday/photos/ntd-jeju-2.webp', '2026-10-18T10:26:00+09:00'::timestamptz, array['제주한라대','재외동포청','재외동포 청년','업무협약','취업']::text[], 'in_review'),
  ('jeju', '제주 레드향 열매터짐 줄인다…농진청, 재배관리 안내자료 제작', '<p>@@BYLINE@@&nbsp;농촌진흥청은 지난 13일 보도자료에서 제주특별자치도농업기술원, 레드향연합회와 함께 ‘레드향’ 열매 터짐(열과) 피해를 줄이기 위한 재배 관리 안내 자료(리플릿)를 만들어 현장 실천형 기술 보급에 나선다고 밝혔다. 기후변화로 늘고 있는 피해를 줄이려는 조치다.</p><p>농촌진흥청에 따르면 레드향은 당도가 높고 풍미가 뛰어난 만감류지만 껍질이 얇아 열매가 갈라지기 쉽다. 열매 터짐 비율은 평년 15~20% 수준이었으나 기온이 높았던 2024년 38.4%, 2025년 30.6%까지 올랐고, 올해는 10월 초 기준 약 20%로 집계됐다.</p><img src="/sites/newstoday/photos/ntd-jeju-3.webp" alt="귤과 레드향(자료사진). 촬영 Scudsvlad, 출처 Wikimedia Commons (CC BY-SA 4.0)"><p><em>▲ 귤과 레드향(자료사진). 촬영 Scudsvlad, 출처 Wikimedia Commons (CC BY-SA 4.0)</em></p><p>열매 터짐은 주로 8~10월 열매가 커지는 시기에 집중된다. 나무가 고온 스트레스를 받거나 토양수분이 급격히 변하고 양분 균형이 맞지 않을 때, 나무 세력이 지나치게 강하거나 열매가 많이 달렸을 때 피해가 커질 수 있다고 농촌진흥청은 설명했다.</p><p>안내 자료는 피해가 컸던 농가의 관리 방법과 개선 방향을 비교해 담고, 온도·물·토양·양분·나무 관리 등 5개 분야의 핵심 기술을 제시했다. 온도 관리는 천창과 측창을 충분히 열고 차광망과 송풍팬을 활용해 7~10월 낮 31도 이하, 밤 24도 이하를 유지하는 것이 중요하다고 했다.</p><p>물 관리는 한꺼번에 많은 양을 주기보다 조금씩 매일 줘 토양수분을 일정하게 유지하라는 내용이다. 나무 밑 풀 재배(초생재배)나 구멍 뚫린 피복재 사용으로 뿌리의 고온 스트레스를 줄이고, 껍질 발달에 필요한 칼슘과 붕소를 적절히 공급하며 열매양도 조절하도록 했다.</p><p>농촌진흥청은 안내 자료를 제주 농업 관련 기관과 농업인 단체 등에 나눠 주고, 피해가 큰 농가에는 현장 기술지원을 하겠다고 밝혔다. 국립원예특작과학원 감귤연구센터장은 “이번 안내 자료는 연구 기관의 재배 기술과 농가의 현장 경험을 종합해 ‘레드향’ 열매 터짐의 복합적인 발생 원인과 실천형 개선 방안을 이해하기 쉽게 담았다”고 밝혔다.</p>', '농촌진흥청이 제주특별자치도농업기술원, 레드향연합회와 함께 기후변화로 늘어난 레드향 열매 터짐 피해를 줄이는 재배 관리 안내 자료를 만들어 현장에 보급한다고 밝혔다. 5개 분야 기술을 담았다.', '/sites/newstoday/photos/ntd-jeju-3.webp', '2026-10-13T10:35:00+09:00'::timestamptz, array['레드향','제주','열매 터짐','농촌진흥청','감귤']::text[], 'in_review'),
  ('jeju', '제주서 구조된 붉은바다거북, 7년 치료 끝에 바다로 돌아간다', '<p>@@BYLINE@@&nbsp;해양수산부는 14일 보도자료에서 제주 해안에서 심하게 다친 채 구조돼 약 7년간 치료와 보호를 받은 붉은바다거북을 15일 서귀포시 성산읍 광치기해변에서 자연으로 돌려보낸다고 밝혔다. 이 개체는 2019년 8월 27일 서귀포시 성산읍 해안가에서 좌초된 상태로 발견됐다.</p><p>구조 당시 그물과 낚시도구 등으로 왼쪽 상완부가 노출되고 오른쪽 어깨 근육과 식도가 손상됐으며, 빈혈도 확인됐다. 장기간 치료가 필요한 상태였다고 해수부는 설명했다.</p><img src="/sites/newstoday/photos/ntd-jeju-4.webp" alt="붉은바다거북(자료사진, 이번 방류 개체 아님). 촬영 ukanda, 출처 Wikimedia Commons (CC BY 2.0)"><p><em>▲ 붉은바다거북(자료사진, 이번 방류 개체 아님). 촬영 ukanda, 출처 Wikimedia Commons (CC BY 2.0)</em></p><p>구조부터 치료와 보호까지는 해양 동물 전문 구조·치료기관으로 지정된 아쿠아플라넷 제주가 맡았다. 손상 부위 봉합과 반복된 염증 제거를 위해 모두 7차례 수술을 했고, 바다거북으로는 처음으로 특수장비를 이용한 음압 치료도 병행했다.</p><p>치료 과정에서 어깨와 목 부위 염증이 되풀이돼 어려움이 있었다. 올해 2월 마지막 수술에서 남은 염증 조직을 제거한 뒤 건강 상태가 좋아졌다고 해수부는 밝혔다.</p><p>방류 장소인 광치기해변은 처음 구조된 지역과 가깝고, 모래사장에서 거북이 스스로 바다까지 이동하기에 적합한 곳이다. 해수부는 개체의 스트레스를 줄이기 위해 위성 추적 장치와 개체 인식표는 달지 않을 예정이라고 밝혔다.</p><p>서정호 해양수산부 해양정책실장은 “이번 방류가 있기까지 지난 7년간의 치료와 회복을 위해 힘써주신 수의사와 사육사 등 관계자분들의 헌신에 감사드린다”고 말했다. 해수부는 조난·부상 해양동물의 구조와 치료, 자연 복귀까지 보호 체계를 계속 강화하겠다는 방침이다.</p>', '해양수산부는 2019년 제주 해안에서 크게 다쳐 구조된 붉은바다거북이 7년간 치료와 보호를 받은 뒤 15일 서귀포시 성산읍 광치기해변에서 자연으로 돌아간다고 14일 밝혔다. 치료에는 수술 7차례가 있었다.', '/sites/newstoday/photos/ntd-jeju-4.webp', '2026-10-14T11:22:00+09:00'::timestamptz, array['붉은바다거북','제주','해양수산부','방류','광치기해변']::text[], 'in_review'),
  ('jeju', '제107회 전국체전 제주서 개막…22일까지 50개 종목 열전', '<p>@@BYLINE@@&nbsp;제107회 전국체육대회가 16일부터 22일까지 제주특별자치도 일원에서 열린다. 문화체육관광부는 16일 보도자료에서 개회식이 이날 오후 6시 제주월드컵경기장에서 열리며, 최휘영 문체부 장관이 참석해 대회 개회를 선언한다고 밝혔다.</p><p>올해 대회는 문체부가 후원하고 대한체육회가 주최한다. 제주특별자치도와 제주특별자치도교육청, 제주특별자치도체육회가 공동으로 주관한다. 선수 2만 명과 임원 1만 명 등 3만여 명이 참가해 18세 이하부, 대학부, 일반부, 해외동포부로 나뉘어 겨룬다. 경기 종목은 정식종목 49개와 시범종목 1개(주짓수)를 합쳐 모두 50개이며, 강창학종합경기장 등 제주 일원 74개 경기장에서 진행된다.</p><img src="/sites/newstoday/photos/ntd-jeju-5.webp" alt="개·폐회식이 열리는 제주월드컵경기장 외관(자료사진). 촬영 thddbwnd, 출처 Wikimedia Commons (CC BY 3.0)"><p><em>▲ 개·폐회식이 열리는 제주월드컵경기장 외관(자료사진). 촬영 thddbwnd, 출처 Wikimedia Commons (CC BY 3.0)</em></p><p>문체부는 9월 19일부터 10월 4일까지 열린 2026 아이치-나고야 아시안게임에서 활약한 국가대표 선수들이 다수 출전한다고 밝혔다. 오상욱(펜싱)과 김우진(양궁) 등이 이름을 올렸고, 이번 아시안게임 유도 은메달리스트 이현지 선수가 개회식 최종 성화 주자로 나선다.</p><p>개회식은 KBS 1TV로 생중계되며, 모든 경기는 누구나 무료로 관람할 수 있다. 종목별 경기 일정과 장소는 대회 공식 누리집에서 확인할 수 있다고 문체부는 안내했다.</p><p>대회 상징도 제주를 담았다. 엠블럼은 제주의 영문 첫 글자 ‘J’를 바탕으로 성화와 푸른 바다를 상징하는 물결을 배치했고, 마스코트 ‘끼요’는 제주 남방큰돌고래를 모티프로 만들었다.</p>', '제107회 전국체육대회가 16일 제주특별자치도 일원에서 개막한다. 22일까지 선수 2만 명 등 3만여 명이 참가해 50개 종목 경기를 치르며, 개회식은 제주월드컵경기장에서 열린다.', '/sites/newstoday/photos/ntd-jeju-5.webp', '2026-10-16T09:03:00+09:00'::timestamptz, array['전국체육대회','제주','제주월드컵경기장','전국체전','개막']::text[], 'in_review')
) as v(slug, title, body, excerpt, thumb, published_at, tags, status)
join categories c on c.outlet_id = ctx.outlet_id and c.slug = v.slug
where ctx.author_id is not null
  and not exists (select 1 from articles a where a.outlet_id = ctx.outlet_id and a.title = v.title);

-- 기자명 '편집국', 기자 이메일 비우기, AI 메모(확인할 점·원문 주소·사진 이용 조건)
--   (기자 이메일은 DB 규칙이 대표 이메일로 채우므로, 잠깐 그 규칙을 끄고 비운 뒤 다시 켠다)
do $fix$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline') then
    update articles a set byline = '편집국'
    from outlets o, (values
      ('청계천 자율주행버스 ''청계 A01'', 22일부터 야간 정기운행'),
      ('광화문광장 감사의 정원 방문객 50만 명 넘어…스웨덴 행사 열려'),
      ('서울, 타임아웃 세계 대중교통 도시 5위…CNN도 서울 지하철 소개'),
      ('서울시, 자치구 생활권 ''서울별빛명소'' 조성…10월 말 10곳 선정'),
      ('안산 경기지방정원 ''새로숲''에 11월부터 나무 심는다'),
      ('포천서 경기북부 긴급구조종합훈련…헬기 추락 복합재난 가정'),
      ('경기도주식회사·연천 전곡농협, 연천쌀 미국 수출 선적식'),
      ('경기도서관 ''책 만들기 프로그램'' 2기 출판기념회…도민 도서 38권 제작'),
      ('경기경제청, 안산사이언스밸리서 일본기업 초청 현장 투자설명회'),
      ('인천시, 인천애뜰 공영주차장 요금 감면… 전기차 충전 27면 설치'),
      ('인천시, 영종~덕적 도심항공교통 실증 마쳐… 도서지역 공공수요 점검'),
      ('인천 선수단, 전국기능경기대회 종합 10위… 인천시 해단식 열어'),
      ('송도에 글로벌 바이오 캠퍼스 실습교육장 개소… 백신 인력 양성'),
      ('인천시, 옹진 대이작 해역에 어린 참담치 35만 마리 방류'),
